def enviar_notificacion_telegram(mensaje):
    """
    Enva una notificacin a Telegram usando el bot configurado.
    Retorna True si se envi correctamente, False si fall.
    """
    try:
        # Obtener configuracin desde la base de datos
        conn = get_db_connection()
        config = conn.execute('SELECT telegram_token, telegram_chat_id, notificaciones_activas FROM CONFIGURACION_SISTEMA WHERE id = 1').fetchone()
        conn.close()

        if not config or not config[2]:  # notificaciones_activas es el ndice 2
            print(" Notificaciones Telegram desactivadas")
            return False

        token = config[0]  # telegram_token
        chat_id = config[1]  # telegram_chat_id

        if not token or not chat_id:
            print(" Token o Chat ID de Telegram no configurado")
            return False

        # Enviar mensaje a Telegram
        url = f"https://api.telegram.org/bot{token}/sendMessage"
        data = {
            'chat_id': chat_id,
            'text': mensaje,
            'parse_mode': 'HTML'
        }

        response = requests.post(url, json=data, timeout=10)

        if response.status_code == 200:
            print(f" Notificacin Telegram enviada correctamente")
            return True
        else:
            print(f" Error enviando Telegram: {response.status_code} - {response.text}")
            return False

    except Exception as e:
        print(f" Excepcin enviando Telegram: {e}")
        import traceback
        traceback.print_exc()
        return False


def enviar_telegram(telefono, mensaje):
    """
    Envía un mensaje de Telegram a un usuario identificado por su teléfono.
    Busca el telegram_chat_id asociado al teléfono en la tabla terceros.
    Retorna True si se envió correctamente, False si falló.
    """
    try:
        # Buscar el telegram_chat_id del tercero con ese teléfono
        import psycopg2
        database_url = os.getenv('DATABASE_URL')
        pg_conn = psycopg2.connect(database_url)
        cursor = pg_conn.cursor()

        cursor.execute('''
            SELECT telegram_chat_id FROM terceros
            WHERE telefono = %s AND telegram_chat_id IS NOT NULL
            LIMIT 1
        ''', (telefono,))
        result = cursor.fetchone()

        if not result or not result[0]:
            print(f"⚠️ No se encontró telegram_chat_id para teléfono {telefono}")
            cursor.close()
            pg_conn.close()
            return False

        chat_id = result[0]

        # Obtener token de Telegram
        cursor.execute('SELECT telegram_token FROM "CONFIGURACION_SISTEMA" LIMIT 1')
        config = cursor.fetchone()
        cursor.close()
        pg_conn.close()

        if not config or not config[0]:
            print("⚠️ Token de Telegram no configurado")
            return False

        token = config[0]

        # Enviar mensaje a Telegram
        url = f"https://api.telegram.org/bot{token}/sendMessage"
        data = {
            'chat_id': chat_id,
            'text': mensaje,
            'parse_mode': 'Markdown'
        }

        response = requests.post(url, json=data, timeout=10)

        if response.status_code == 200:
            print(f"✅ Mensaje Telegram enviado a {telefono} (chat_id: {chat_id})")
            return True
        else:
            print(f"❌ Error enviando Telegram: {response.status_code} - {response.text}")
            return False

    except Exception as e:
        print(f"❌ Excepción enviando Telegram: {e}")
        import traceback
        traceback.print_exc()
        return False


