@app.route('/admin/cargar_pois')
@admin_required
def cargar_pois():
    """Carga los POIs de Cali desde el archivo JSON a la base de datos"""
    import json

    try:
        conn = get_db_connection()
        resultados = []

        # 0. Crear extensiones necesarias para búsqueda
        conn.execute("CREATE EXTENSION IF NOT EXISTS unaccent;")
        conn.execute("CREATE EXTENSION IF NOT EXISTS pg_trgm;")
        resultados.append("✅ Extensiones unaccent y pg_trgm habilitadas")

        # 1. Crear tabla pois_cali
        conn.execute("""
            CREATE TABLE IF NOT EXISTS pois_cali (
                id SERIAL PRIMARY KEY,
                osm_id BIGINT,
                nombre VARCHAR(255) NOT NULL,
                lat DECIMAL(10, 8) NOT NULL,
                lon DECIMAL(11, 8) NOT NULL,
                categoria VARCHAR(50),
                subcategoria VARCHAR(100),
                direccion VARCHAR(255),
                display_name TEXT,
                barrio VARCHAR(100),
                fecha_creacion TIMESTAMP DEFAULT CURRENT_TIMESTAMP
            );
        """)
        resultados.append("✅ Tabla pois_cali creada")

        # 2. Crear índices
        conn.execute("CREATE INDEX IF NOT EXISTS idx_pois_nombre ON pois_cali(LOWER(nombre));")
        conn.execute("CREATE INDEX IF NOT EXISTS idx_pois_categoria ON pois_cali(categoria);")
        conn.execute("CREATE INDEX IF NOT EXISTS idx_pois_coords ON pois_cali(lat, lon);")
        resultados.append("✅ Índices creados")

        # 3. Cargar archivo JSON
        archivo_json = 'scripts/pois_cali.json'
        try:
            with open(archivo_json, 'r', encoding='utf-8') as f:
                pois = json.load(f)
            resultados.append(f"✅ Archivo cargado: {len(pois)} POIs")
        except FileNotFoundError:
            conn.close()
            return f"<h1>❌ Error:</h1><pre>Archivo {archivo_json} no encontrado</pre>", 404

        # 4. Limpiar datos anteriores
        conn.execute("DELETE FROM pois_cali;")
        resultados.append("✅ Tabla limpiada")

        # 5. Insertar POIs
        insertados = 0
        errores = 0

        for poi in pois:
            try:
                conn.execute("""
                    INSERT INTO pois_cali (osm_id, nombre, lat, lon, categoria, subcategoria, direccion, display_name, barrio)
                    VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s)
                """, (
                    poi.get('osm_id'),
                    poi.get('nombre', '')[:255],
                    poi.get('lat'),
                    poi.get('lon'),
                    poi.get('categoria'),
                    poi.get('subcategoria'),
                    poi.get('direccion', '')[:255] if poi.get('direccion') else None,
                    poi.get('display_name'),
                    poi.get('barrio', '')[:100] if poi.get('barrio') else None
                ))
                insertados += 1
            except Exception as e:
                errores += 1
                if errores <= 5:
                    resultados.append(f"⚠️ Error en {poi.get('nombre', 'sin nombre')}: {str(e)[:50]}")

        conn.commit()
        conn.close()

        resultados.append(f"✅ POIs insertados: {insertados}")
        if errores > 0:
            resultados.append(f"⚠️ Errores: {errores}")

        resultados_html = "<br>".join(resultados)
        return f"""
        <h1>✅ POIs de Cali cargados</h1>
        <div style="font-family: monospace; padding: 20px;">
            {resultados_html}
        </div>
        <br>
        <a href="/admin/parametros" style="padding: 10px 20px; background: #4CAF50; color: white; text-decoration: none; border-radius: 5px;">Volver a Parámetros</a>
        """

    except Exception as e:
        import traceback
        traceback.print_exc()
        return f"<h1>❌ Error:</h1><pre>{str(e)}</pre>", 500


@app.route('/admin/setup_festivos_table')
@admin_required
def setup_festivos_table():
    """Crea la tabla festivos e inserta festivos de Colombia 2026"""
    try:
        conn = get_db_connection()

        # Crear tabla festivos
        conn.execute("""
            CREATE TABLE IF NOT EXISTS festivos (
                id SERIAL PRIMARY KEY,
                fecha DATE NOT NULL UNIQUE,
                nombre VARCHAR(100) NOT NULL,
                activo BOOLEAN DEFAULT TRUE,
                fecha_creacion TIMESTAMP DEFAULT CURRENT_TIMESTAMP
            );
        """)

        # Crear índices
        conn.execute("CREATE INDEX IF NOT EXISTS idx_festivos_fecha ON festivos(fecha);")
        conn.execute("CREATE INDEX IF NOT EXISTS idx_festivos_activo ON festivos(activo);")

        # Verificar si ya hay datos
        count_antes = conn.execute("SELECT COUNT(*) as cnt FROM festivos").fetchone()['cnt']

        # Insertar festivos de Colombia 2026 (si no existen)
        festivos_2026 = [
            ('2026-01-01', 'Año Nuevo'),
            ('2026-01-12', 'Día de los Reyes Magos'),
            ('2026-03-23', 'Día de San José'),
            ('2026-04-02', 'Jueves Santo'),
            ('2026-04-03', 'Viernes Santo'),
            ('2026-05-01', 'Día del Trabajo'),
            ('2026-05-18', 'Ascensión del Señor'),
            ('2026-06-08', 'Corpus Christi'),
            ('2026-06-15', 'Sagrado Corazón'),
            ('2026-06-29', 'San Pedro y San Pablo'),
            ('2026-07-20', 'Día de la Independencia'),
            ('2026-08-07', 'Batalla de Boyacá'),
            ('2026-08-17', 'Asunción de la Virgen'),
            ('2026-10-12', 'Día de la Raza'),
            ('2026-11-02', 'Todos los Santos'),
            ('2026-11-16', 'Independencia de Cartagena'),
            ('2026-12-08', 'Inmaculada Concepción'),
            ('2026-12-25', 'Navidad')
        ]

        for fecha, nombre in festivos_2026:
            # Verificar si ya existe antes de insertar
            existe = conn.execute("SELECT id FROM festivos WHERE fecha = %s", (fecha,)).fetchone()
            if not existe:
                conn.execute("INSERT INTO festivos (fecha, nombre) VALUES (%s, %s)", (fecha, nombre))

        conn.commit()

        # Contar después
        count_despues = conn.execute("SELECT COUNT(*) as cnt FROM festivos").fetchone()['cnt']
        insertados = count_despues - count_antes

        # Mostrar festivos actuales
        festivos = conn.execute("SELECT fecha, nombre FROM festivos WHERE activo = TRUE ORDER BY fecha").fetchall()
        festivos_html = "".join([f"<li>{f['fecha']} - {f['nombre']}</li>" for f in festivos])

        return f"""
        <h1>✅ Tabla festivos configurada</h1>
        <p>Tabla creada correctamente</p>
        <p>Índices creados</p>
        <p>Festivos existentes antes: {count_antes}</p>
        <p>Festivos insertados: {insertados}</p>
        <p>Total festivos activos: {count_despues}</p>
        <h3>Festivos 2026:</h3>
        <ul>{festivos_html}</ul>
        <br>
        <a href="/admin/parametros">Volver a Parámetros</a>
        """
    except Exception as e:
        import traceback
        traceback.print_exc()
        return f"<h1>❌ Error:</h1><pre>{str(e)}</pre>", 500

