@app.route('/admin/diagnosticos/<int:diagnostico_id>/sintomas/quitar', methods=['POST'])
def quitar_sintoma_diagnostico(diagnostico_id):
    """Desasocia un sntoma de un diagnstico"""
    data = request.get_json()
