@app.route('/api/parametro/<nombre_parametro>', methods=['GET', 'POST'])
@admin_required
def parametro_sistema(nombre_parametro):
    """GET: Obtiene el valor de un parámetro / POST: Actualiza el valor"""

    if request.method == 'GET':
        try:
            conn = get_db_connection()

            row = conn.execute("""
                SELECT valor_numerico, valor_texto, valor_booleano, tipo
                FROM parametros_sistema
                WHERE nombre = %s
            """, (nombre_parametro,)).fetchone()

            conn.close()

            if row:
                # Retornar el valor según el tipo
                if row['tipo'] == 'numerico':
                    valor = row['valor_numerico']
                elif row['tipo'] == 'texto':
                    valor = row['valor_texto']
                elif row['tipo'] == 'booleano':
                    valor = row['valor_booleano']
                else:
                    valor = None

                return jsonify({'ok': True, 'valor': valor, 'tipo': row['tipo']})
            else:
                return jsonify({'ok': False, 'error': 'Parámetro no encontrado', 'valor': None})

        except Exception as e:
            print(f"Error obteniendo parámetro {nombre_parametro}: {e}")
            import traceback
            traceback.print_exc()
            return jsonify({'ok': False, 'error': str(e), 'valor': None}), 500

    elif request.method == 'POST':
        try:
            data = request.get_json()
            valor = data.get('valor')

            if valor is None:
                return jsonify({'ok': False, 'error': 'Valor no proporcionado'}), 400

            conn = get_db_connection()

            # Verificar si el parámetro existe
            row = conn.execute("""
                SELECT tipo FROM parametros_sistema WHERE nombre = %s
            """, (nombre_parametro,)).fetchone()

            if not row:
                # UPSERT: Crear el parámetro si no existe
                # Detectar tipo automáticamente
                # Primero verificar si es booleano (antes de float porque float(True)=1.0)
                if isinstance(valor, bool) or str(valor).lower() in ('true', 'false'):
                    tipo_auto = 'booleano'
                elif ':' in str(valor):
                    # Si parece hora (HH:MM), es texto
                    tipo_auto = 'texto'
                else:
                    try:
                        float(valor)
                        tipo_auto = 'numerico'
                    except (ValueError, TypeError):
                        tipo_auto = 'texto'

                # Insertar nuevo parámetro (sin columna seccion que no existe en producción)
                if tipo_auto == 'numerico':
                    conn.execute("""
                        INSERT INTO parametros_sistema (nombre, tipo, valor_numerico)
                        VALUES (%s, %s, %s)
                    """, (nombre_parametro, tipo_auto, float(valor)))
                elif tipo_auto == 'texto':
                    conn.execute("""
                        INSERT INTO parametros_sistema (nombre, tipo, valor_texto)
                        VALUES (%s, %s, %s)
                    """, (nombre_parametro, tipo_auto, str(valor)))
                elif tipo_auto == 'booleano':
                    conn.execute("""
                        INSERT INTO parametros_sistema (nombre, tipo, valor_booleano)
                        VALUES (%s, %s, %s)
                    """, (nombre_parametro, tipo_auto, str(valor).lower() == 'true'))

                conn.commit()
                conn.close()
                return jsonify({'ok': True, 'message': 'Parámetro creado correctamente'})

            # Si existe, actualizar según el tipo
            tipo = row['tipo']

            # Si el valor enviado es booleano pero el tipo guardado no lo es, corregir
            if isinstance(valor, bool) and tipo != 'booleano':
                conn.execute("""
                    UPDATE parametros_sistema
                    SET tipo = 'booleano', valor_booleano = %s, fecha_actualizacion = CURRENT_TIMESTAMP
                    WHERE nombre = %s
                """, (valor, nombre_parametro))
            elif tipo == 'numerico':
                conn.execute("""
                    UPDATE parametros_sistema
                    SET valor_numerico = %s, fecha_actualizacion = CURRENT_TIMESTAMP
                    WHERE nombre = %s
                """, (float(valor), nombre_parametro))
            elif tipo == 'texto':
                conn.execute("""
                    UPDATE parametros_sistema
                    SET valor_texto = %s, fecha_actualizacion = CURRENT_TIMESTAMP
                    WHERE nombre = %s
                """, (str(valor), nombre_parametro))
            elif tipo == 'booleano':
                # Manejar tanto booleanos Python como strings 'true'/'false'
                valor_bool = valor if isinstance(valor, bool) else str(valor).lower() == 'true'
                conn.execute("""
                    UPDATE parametros_sistema
                    SET valor_booleano = %s, fecha_actualizacion = CURRENT_TIMESTAMP
                    WHERE nombre = %s
                """, (valor_bool, nombre_parametro))

            conn.commit()
            conn.close()

            return jsonify({'ok': True, 'message': 'Parámetro actualizado correctamente'})

        except Exception as e:
            print(f"Error actualizando parámetro {nombre_parametro}: {e}")
            import traceback
            traceback.print_exc()
            return jsonify({'ok': False, 'error': str(e)}), 500


