@app.route('/api/pastilleros/crear', methods=['POST'])
def api_crear_pastillero():
    """Crear un nuevo pastillero"""
    if 'usuario_id' not in session:
        return jsonify({'ok': False, 'error': 'No autenticado'}), 401

    usuario_id = session['usuario_id']
    data = request.get_json()
    nombre = data.get('nombre', '').strip()

    if not nombre:
        return jsonify({'ok': False, 'error': 'Falta nombre del pastillero'}), 400

    try:
        conn = get_db_connection()

        # Crear pastillero
        conn.execute('''
            INSERT INTO pastilleros (nombre, creado_por_usuario_id)
            VALUES (%s, %s)
        ''', (nombre, usuario_id))

        # Obtener el ID del pastillero creado
        pastillero_id = conn.execute('''
            SELECT id FROM pastilleros
            WHERE creado_por_usuario_id = %s
            ORDER BY id DESC LIMIT 1
        ''', (usuario_id,)).fetchone()['id']

        # Crear relación de propietario
        conn.execute('''
            INSERT INTO relaciones_pastillero (pastillero_id, usuario_id, tipo)
            VALUES (%s, %s, 'propietario')
        ''', (pastillero_id, usuario_id))

        conn.commit()
        conn.close()

        return jsonify({'ok': True, 'pastillero_id': pastillero_id})
    except Exception as e:
        print(f"Error al crear pastillero: {e}")
        return jsonify({'ok': False, 'error': str(e)}), 500


@app.route('/api/pastilleros/compartir', methods=['POST'])
def api_compartir_pastillero():
    """Enviar invitación para compartir pastillero"""
    if 'usuario_id' not in session:
        return jsonify({'ok': False, 'error': 'No autenticado'}), 401

    usuario_id = session['usuario_id']
    data = request.get_json()

    pastillero_id = data.get('pastillero_id')
    destinatario_id = data.get('destinatario_id')
    tipo_acceso = data.get('tipo_acceso', 'miembro')  # 'miembro' o 'autorizado'

    if not pastillero_id or not destinatario_id:
        return jsonify({'ok': False, 'error': 'Faltan datos'}), 400

    try:
        conn = get_db_connection()

        # Verificar que el usuario es propietario del pastillero
        es_propietario = conn.execute('''
            SELECT id FROM relaciones_pastillero
            WHERE pastillero_id = %s AND usuario_id = %s AND tipo = 'propietario'
        ''', (pastillero_id, usuario_id)).fetchone()

        if not es_propietario:
            conn.close()
            return jsonify({'ok': False, 'error': 'Solo el propietario puede compartir'}), 403

        # Obtener nombre del pastillero
        pastillero = conn.execute('''
            SELECT nombre FROM pastilleros WHERE id = %s
        ''', (pastillero_id,)).fetchone()

        # Crear mensaje de invitación
        tipo_msg = 'invitacion_compartir' if tipo_acceso == 'miembro' else 'solicitud_acceso'
        mensaje_texto = f"Te invito a {'compartir' if tipo_acceso == 'miembro' else 'ver'} mi pastillero '{pastillero['nombre']}'"

        conn.execute('''
            INSERT INTO mensajes (remitente_id, destinatario_id, mensaje, tipo, pastillero_id, estado, fecha)
            VALUES (%s, %s, %s, %s, %s, 'pendiente', CURRENT_TIMESTAMP)
        ''', (usuario_id, destinatario_id, mensaje_texto, tipo_msg, pastillero_id))

        conn.commit()
        conn.close()

        return jsonify({'ok': True})
    except Exception as e:
        print(f"Error al compartir pastillero: {e}")
        return jsonify({'ok': False, 'error': str(e)}), 500


@app.route('/api/pastilleros/responder-invitacion', methods=['POST'])
def api_responder_invitacion():
    """Aceptar o rechazar invitación de pastillero"""
    if 'usuario_id' not in session:
        return jsonify({'ok': False, 'error': 'No autenticado'}), 401

    usuario_id = session['usuario_id']
    data = request.get_json()

    mensaje_id = data.get('mensaje_id')
    aceptar = data.get('aceptar', False)

    if not mensaje_id:
        return jsonify({'ok': False, 'error': 'Falta mensaje_id'}), 400

    try:
        conn = get_db_connection()

        # Obtener el mensaje
        mensaje = conn.execute('''
            SELECT * FROM mensajes
            WHERE id = %s AND destinatario_id = %s
        ''', (mensaje_id, usuario_id)).fetchone()

        if not mensaje:
            conn.close()
            return jsonify({'ok': False, 'error': 'Mensaje no encontrado'}), 404

        if aceptar:
            # Determinar el tipo de acceso
            tipo = 'miembro' if mensaje['tipo'] == 'invitacion_compartir' else 'autorizado'

            # Agregar al pastillero
            conn.execute('''
                INSERT INTO relaciones_pastillero (pastillero_id, usuario_id, tipo)
                VALUES (%s, %s, %s)
                ON CONFLICT DO NOTHING
            ''', (mensaje['pastillero_id'], usuario_id, tipo))

            # Marcar mensaje como aceptado
            conn.execute('''
                UPDATE mensajes SET estado = 'aceptado' WHERE id = %s
            ''', (mensaje_id,))
        else:
            # Marcar mensaje como rechazado
            conn.execute('''
                UPDATE mensajes SET estado = 'rechazado' WHERE id = %s
            ''', (mensaje_id,))

        conn.commit()
        conn.close()

        return jsonify({'ok': True})
    except Exception as e:
        print(f"Error al responder invitación: {e}")
        return jsonify({'ok': False, 'error': str(e)}), 500


@app.route('/api/pastillero/alertas', methods=['GET'])
def api_obtener_alertas_pastillero():
    """
    Obtiene medicamentos que requieren reposición
    - Botiquín: cuando cantidad <= nivel_minimo_alerta
    - Tratamiento: cuando tomas pendientes > cantidad disponible
    """
    if 'usuario_id' not in session:
        return jsonify({'ok': False, 'error': 'No autenticado'}), 401

    usuario_id = session['usuario_id']

    try:
        conn = get_db_connection()

        # Obtener pastillero activo
        pastillero_id = session.get('pastillero_activo_id')
        if not pastillero_id:
            pastillero = conn.execute("""
                SELECT p.id FROM pastilleros p
                INNER JOIN relaciones_pastillero rp ON p.id = rp.pastillero_id
                WHERE rp.usuario_id = %s AND rp.tipo IN ('propietario', 'miembro')
                ORDER BY rp.tipo DESC, p.id ASC
                LIMIT 1
            """, (usuario_id,)).fetchone()

            if not pastillero:
                conn.close()
                return jsonify({'ok': True, 'alertas': []})

            pastillero_id = pastillero['id']

        # ALERTAS DE BOTIQUÍN: cantidad <= nivel_minimo_alerta
        alertas_botiquin = conn.execute("""
            SELECT
                p.id,
                p.nombre,
                p.medicamento_id,
                p.cantidad,
                p.unidad,
                p.nivel_minimo_alerta,
                'botiquin' as tipo_alerta,
                'Quedan ' || p.cantidad || ' ' || p.unidad || ' (mínimo: ' || p.nivel_minimo_alerta || ')' as mensaje
            FROM pastillero_usuarios p
            WHERE p.pastillero_id = %s
              AND p.tipo_medicamento = 'botiquin'
              AND p.alerta_reposicion = TRUE
              AND p.cantidad <= p.nivel_minimo_alerta
              AND (p.alerta_pospuesta_hasta IS NULL OR p.alerta_pospuesta_hasta < CURRENT_TIMESTAMP)
            ORDER BY p.cantidad ASC
        """, (pastillero_id,)).fetchall()

        # ALERTAS DE TRATAMIENTO: calcular tomas pendientes
        ahora = datetime.now()
        alertas_tratamiento = []

        medicamentos_tratamiento = conn.execute("""
            SELECT
                p.id,
                p.nombre,
                p.medicamento_id,
                p.cantidad,
                p.unidad,
                p.horas_entre_tomas,
                p.fecha_inicio_tratamiento,
                p.fecha_fin_tratamiento,
                p.tomas_completadas
            FROM pastillero_usuarios p
            WHERE p.pastillero_id = %s
              AND p.tipo_medicamento = 'tratamiento'
              AND p.fecha_fin_tratamiento IS NOT NULL
              AND p.fecha_fin_tratamiento >= %s
              AND (p.alerta_pospuesta_hasta IS NULL OR p.alerta_pospuesta_hasta < CURRENT_TIMESTAMP)
        """, (pastillero_id, ahora.date())).fetchall()

        for med in medicamentos_tratamiento:
            if med['horas_entre_tomas'] and med['fecha_fin_tratamiento']:
                # Calcular días restantes
                dias_restantes = (med['fecha_fin_tratamiento'] - ahora.date()).days

                # Calcular tomas pendientes
                tomas_por_dia = 24 / med['horas_entre_tomas']
                tomas_pendientes = int(dias_restantes * tomas_por_dia)

                # Si faltan más tomas de las que tiene en stock
                if tomas_pendientes > med['cantidad']:
                    faltantes = tomas_pendientes - med['cantidad']
                    alertas_tratamiento.append({
                        'id': med['id'],
                        'nombre': med['nombre'],
                        'medicamento_id': med['medicamento_id'],
                        'cantidad': med['cantidad'],
                        'unidad': med['unidad'],
                        'tomas_pendientes': tomas_pendientes,
                        'tipo_alerta': 'tratamiento',
                        'mensaje': f"Te faltarán {faltantes} tomas para completar el tratamiento"
                    })

        # Combinar alertas
        alertas = [dict(row) for row in alertas_botiquin] + alertas_tratamiento

        conn.close()

        return jsonify({
            'ok': True,
            'alertas': alertas,
            'total': len(alertas)
        })

    except Exception as e:
        print(f"Error al obtener alertas: {e}")
        import traceback
        traceback.print_exc()
        return jsonify({'ok': False, 'error': str(e)}), 500


@app.route('/api/pastillero/alertas/posponer/<int:medicamento_id>', methods=['POST'])
def api_posponer_alerta(medicamento_id):
    """Pospone alerta por 24 horas (botón 'Ahora no')"""
    if 'usuario_id' not in session:
        return jsonify({'ok': False, 'error': 'No autenticado'}), 401

    try:
        conn = get_db_connection()

        # Posponer 24 horas
        proxima_alerta = datetime.now() + timedelta(hours=24)

        conn.execute("""
            UPDATE pastillero_usuarios
            SET alerta_pospuesta_hasta = %s
            WHERE id = %s
        """, (proxima_alerta, medicamento_id))

        conn.commit()
        conn.close()

        return jsonify({'ok': True, 'pospuesta_hasta': proxima_alerta.isoformat()})

    except Exception as e:
        print(f"Error al posponer alerta: {e}")
        return jsonify({'ok': False, 'error': str(e)}), 500


@app.route('/api/pastillero/alertas/desactivar/<int:medicamento_id>', methods=['POST'])
def api_desactivar_alerta(medicamento_id):
    """Desactiva alertas permanentemente (botón 'No recordar más')"""
    if 'usuario_id' not in session:
        return jsonify({'ok': False, 'error': 'No autenticado'}), 401

    try:
        conn = get_db_connection()

        conn.execute("""
            UPDATE pastillero_usuarios
            SET alerta_reposicion = FALSE,
                alerta_pospuesta_hasta = NULL
            WHERE id = %s
        """, (medicamento_id,))

        conn.commit()
        conn.close()

        return jsonify({'ok': True})

    except Exception as e:
        print(f"Error al desactivar alerta: {e}")
        return jsonify({'ok': False, 'error': str(e)}), 500


