# Importar funciones auxiliares
from sugerir_sintomas_helpers import (
    normalizar, detectar_diagnosticos_en_texto,
    extraer_sugeridos_de_texto_avanzado, validar_texto_medicamento,
    normalizar_sintomas_lista, REGLAS_DIAGNOSTICOS
)


@app.route('/admin/sugerir-sintomas', methods=['GET'])
@app.route('/admin/sugerir-sintomas/<int:med_id>', methods=['GET'])
@admin_required
def admin_sugerir_sintomas(med_id=None):
    """Vista principal para sugerir síntomas a medicamentos"""
    try:
        conn = get_db_connection()

        # Si no se especifica medicamento, buscar el primero pendiente
        if med_id is None:
            primer_pendiente = conn.execute("""
                SELECT m.id
                FROM medicamentos m
                LEFT JOIN medicamento_sintoma ms ON m.id = ms.medicamento_id
                WHERE ms.sintoma_id IS NULL
                ORDER BY
                    CASE WHEN m.componente_activo_id IS NULL THEN 1 ELSE 0 END,
                    (SELECT CASE WHEN p.precio > 0 THEN 0 ELSE 1 END FROM precios p WHERE p.medicamento_id = m.id LIMIT 1),
                    m.nombre
                LIMIT 1
            """).fetchone()

            if primer_pendiente:
                conn.close()
                return redirect(url_for('admin_sugerir_sintomas', med_id=primer_pendiente['id']))
            else:
                conn.close()
                return render_template('admin_sugerir_sintomas.html',
                                     medicamento=None,
                                     medicamentos_pendientes=0,
                                     mensaje="✅ No hay medicamentos pendientes")

        # Obtener medicamento actual
        medicamento = conn.execute("""
            SELECT m.id, m.nombre, m.componente_activo_id,
                   ca.nombre as componente_activo_nombre
            FROM medicamentos m
            LEFT JOIN medicamentos ca ON m.componente_activo_id = ca.id
            WHERE m.id = %s
        """, (med_id,)).fetchone()

        if not medicamento:
            conn.close()
            return "Medicamento no encontrado", 404

        # Obtener lista de medicamentos pendientes (para el selector)
        medicamentos_list = conn.execute("""
            SELECT m.id, m.nombre, m.componente_activo_id,
                   CASE WHEN p.precio > 0 THEN 1 ELSE 0 END as tiene_precio
            FROM medicamentos m
            LEFT JOIN medicamento_sintoma ms ON m.id = ms.medicamento_id
            LEFT JOIN precios p ON p.medicamento_id = m.id
            WHERE ms.sintoma_id IS NULL
            ORDER BY
                CASE WHEN m.componente_activo_id IS NULL THEN 1 ELSE 0 END,
                CASE WHEN p.precio > 0 THEN 0 ELSE 1 END,
                m.nombre
            LIMIT 200
        """).fetchall()

        # Contar total pendientes
        total_pendientes = conn.execute("""
            SELECT COUNT(DISTINCT m.id) as total
            FROM medicamentos m
            LEFT JOIN medicamento_sintoma ms ON m.id = ms.medicamento_id
            WHERE ms.sintoma_id IS NULL
        """).fetchone()['total']

        # Determinar término de búsqueda (componente activo si existe, sino nombre)
        termino_busqueda = medicamento['nombre']
        if medicamento['componente_activo_nombre']:
            termino_busqueda = medicamento['componente_activo_nombre']

        conn.close()

        # Renderizar template con headers anti-caché
        response = make_response(render_template('admin_sugerir_sintomas.html',
                             medicamento=medicamento,
                             medicamentos_list=medicamentos_list,
                             total_pendientes=total_pendientes,
                             termino_busqueda=termino_busqueda))

        # Prevenir caché del navegador y CDN
        response.headers['Cache-Control'] = 'no-cache, no-store, must-revalidate, private'
        response.headers['Pragma'] = 'no-cache'
        response.headers['Expires'] = '0'

        return response

    except Exception as e:
        print(f"Error en admin_sugerir_sintomas: {e}")
        traceback.print_exc()
        return jsonify({'ok': False, 'error': str(e)}), 500


@app.route('/admin/sugerir-sintomas/filtrar', methods=['GET'])
@admin_required
def filtrar_medicamentos_sugerir():
    """Filtra medicamentos según tipo y precio"""
    try:
        filtro_tipo = request.args.get('tipo', 'todos')  # todos, genericos, comerciales
        filtro_precio = request.args.get('precio', 'todos')  # todos, con, sin

        conn = get_db_connection()

        where_clauses = ["ms.sintoma_id IS NULL"]

        if filtro_tipo == 'genericos':
            where_clauses.append("m.componente_activo_id IS NULL")
        elif filtro_tipo == 'comerciales':
            where_clauses.append("m.componente_activo_id IS NOT NULL")

        if filtro_precio == 'con':
            where_clauses.append("p.precio > 0")
        elif filtro_precio == 'sin':
            where_clauses.append("(p.precio IS NULL OR p.precio <= 0)")

        where_sql = " AND ".join(where_clauses)

        # Usar el wrapper correctamente sin f-string para que convierta nombres de tablas
        # Agregar las expresiones de ORDER BY al SELECT para cumplir con PostgreSQL DISTINCT
        query = """
            SELECT DISTINCT
                m.id,
                m.nombre,
                m.componente_activo_id,
                ca.nombre as componente_activo_nombre,
                CASE WHEN p.precio > 0 THEN 1 ELSE 0 END as tiene_precio,
                CASE WHEN m.componente_activo_id IS NULL THEN 1 ELSE 0 END as es_generico_sort,
                CASE WHEN p.precio > 0 THEN 0 ELSE 1 END as sin_precio_sort
            FROM medicamentos m
            LEFT JOIN medicamento_sintoma ms ON m.id = ms.medicamento_id
            LEFT JOIN precios p ON p.medicamento_id = m.id
            LEFT JOIN componentes_activos ca ON ca.id = m.componente_activo_id
            WHERE """ + where_sql + """
            ORDER BY es_generico_sort, sin_precio_sort, m.nombre
            LIMIT 200
        """
        medicamentos = conn.execute(query).fetchall()

        conn.close()

        return jsonify({
            'ok': True,
            'medicamentos': [{
                'id': m['id'],
                'nombre': m['nombre'],
                'es_generico': m['componente_activo_id'] is None,
                'tiene_precio': m['tiene_precio'] == 1,
                'componente_activo_nombre': m['componente_activo_nombre']
            } for m in medicamentos]
        })

    except Exception as e:
        print(f"Error filtrando medicamentos: {e}")
        return jsonify({'ok': False, 'error': str(e)}), 500


@app.route('/admin/sugerir-sintomas/procesar-texto/<int:med_id>', methods=['POST'])
@admin_required
def procesar_texto_pegado(med_id):
    """Procesa el texto pegado y detecta síntomas/diagnósticos"""
    try:
        data = request.get_json()
        texto = data.get('texto', '').strip()

        if not texto or len(texto) < 20:
            return jsonify({'ok': False, 'error': 'Texto muy corto (mínimo 20 caracteres)'}), 400

        conn = get_db_connection()

        # Obtener medicamento
        medicamento = conn.execute("""
            SELECT m.id, m.nombre, ca.nombre as componente_activo_nombre
            FROM medicamentos m
            LEFT JOIN medicamentos ca ON m.componente_activo_id = ca.id
            WHERE m.id = %s
        """, (med_id,)).fetchone()

        if not medicamento:
            conn.close()
            return jsonify({'ok': False, 'error': 'Medicamento no encontrado'}), 404

        # VALIDAR si el texto corresponde al medicamento
        nombre_validar = medicamento['componente_activo_nombre'] or medicamento['nombre']
        coincide, confianza = validar_texto_medicamento(texto, nombre_validar)

        # Detectar diagnósticos
        diagnosticos_detectados_raw = detectar_diagnosticos_en_texto(texto)

        # Procesar diagnósticos
        diagnosticos_resultado = []
        sintomas_derivados = set()

        for d_raw in diagnosticos_detectados_raw:
            d_nombre = d_raw['nombre']
            d_sintomas = d_raw['sintomas']

            # Verificar si el diagnóstico existe en la BD
            d_bd = conn.execute(
                'SELECT id FROM diagnosticos WHERE LOWER(descripcion) = %s',
                (d_nombre.lower(),)
            ).fetchone()

            d_id = d_bd['id'] if d_bd else None

            diagnosticos_resultado.append({
                'nombre': d_nombre.title(),
                'id': d_id,
                'sintomas': d_sintomas,
                'nuevo': not d_id
            })

            # Agregar síntomas derivados
            for sintoma in d_sintomas:
                sintomas_derivados.add(normalizar(sintoma))

        # Extraer síntomas directos del texto
        sintomas_heuristica = extraer_sugeridos_de_texto_avanzado(texto)
        for s in sintomas_heuristica:
            sintomas_derivados.add(normalizar(s))

        # Obtener todos los síntomas de la BD
        sintomas_db = conn.execute('SELECT id, nombre FROM sintomas').fetchall()

        # Matchear síntomas detectados con los de la BD
        sintomas_resultado = []
        for s_norm in sorted(sintomas_derivados):
            encontrado = next(
                (x for x in sintomas_db if normalizar(x['nombre']) == s_norm),
                None
            )

            if encontrado:
                sintomas_resultado.append({
                    'label': encontrado['nombre'],
                    'id': encontrado['id'],
                    'nuevo': False
                })
            else:
                sintomas_resultado.append({
                    'label': s_norm.title(),
                    'id': None,
                    'nuevo': True
                })

        conn.close()

        return jsonify({
            'ok': True,
            'validacion': {
                'coincide': coincide,
                'confianza': confianza,
                'mensaje': f"Confianza: {confianza}%" if not coincide else "Texto validado"
            },
            'diagnosticos': diagnosticos_resultado,
            'sintomas': sintomas_resultado
        })

    except Exception as e:
        print(f"Error procesando texto: {e}")
        traceback.print_exc()
        return jsonify({'ok': False, 'error': str(e)}), 500


@app.route('/admin/buscar-componentes-activos', methods=['GET'])
@admin_required
def buscar_componentes_activos():
    """Busca medicamentos genéricos (componentes activos) por nombre"""
    try:
        query = request.args.get('q', '').strip()

        if len(query) < 2:
            return jsonify({'ok': True, 'componentes': []})

        conn = get_db_connection()

        # Buscar medicamentos que son genéricos (componente_activo_id IS NULL)
        # y cuyo nombre contiene el query
        componentes = conn.execute("""
            SELECT DISTINCT m.id, m.nombre,
                   (SELECT COUNT(*) FROM medicamentos WHERE componente_activo_id = m.id) as num_usos
            FROM medicamentos m
            WHERE m.componente_activo_id IS NULL
              AND LOWER(m.nombre) LIKE LOWER(%s)
            ORDER BY num_usos DESC, m.nombre
            LIMIT 20
        """, (f'%{query}%',)).fetchall()

        conn.close()

        resultados = []
        for comp in componentes:
            resultados.append({
                'id': comp['id'],
                'nombre': comp['nombre'],
                'usado_en': f"{comp['num_usos']} productos" if comp['num_usos'] > 0 else None
            })

        return jsonify({'ok': True, 'componentes': resultados})

    except Exception as e:
        print(f"Error buscando componentes activos: {e}")
        traceback.print_exc()
        return jsonify({'ok': False, 'error': str(e)}), 500


@app.route('/admin/asignar-componente-activo', methods=['POST'])
@admin_required
def asignar_componente_activo():
    """Asigna un componente activo existente a un medicamento"""
    try:
        data = request.get_json()
        medicamento_id = data.get('medicamento_id')
        componente_activo_id = data.get('componente_activo_id')

        if not medicamento_id or not componente_activo_id:
            return jsonify({'ok': False, 'error': 'Faltan parámetros'}), 400

        conn = get_db_connection()

        # Verificar que el componente activo existe y es genérico
        componente = conn.execute(
            'SELECT id, nombre, componente_activo_id FROM medicamentos WHERE id = %s',
            (componente_activo_id,)
        ).fetchone()

        if not componente:
            conn.close()
            return jsonify({'ok': False, 'error': 'Componente activo no encontrado'}), 404

        if componente['componente_activo_id'] is not None:
            conn.close()
            return jsonify({'ok': False, 'error': 'El medicamento seleccionado no es un componente activo (genérico)'}), 400

        # Asignar componente activo
        conn.execute(
            'UPDATE medicamentos SET componente_activo_id = %s WHERE id = %s',
            (componente_activo_id, medicamento_id)
        )
        conn.commit()
        conn.close()

        return jsonify({
            'ok': True,
            'mensaje': f'Componente activo asignado correctamente',
            'componente_nombre': componente['nombre']
        })

    except Exception as e:
        print(f"Error asignando componente activo: {e}")
        traceback.print_exc()
        return jsonify({'ok': False, 'error': str(e)}), 500


@app.route('/admin/crear-componente-activo', methods=['POST'])
@admin_required
def crear_componente_activo():
    """Crea un nuevo medicamento genérico (componente activo) y lo asigna a un medicamento"""
    try:
        data = request.get_json()
        nombre = data.get('nombre', '').strip()
        medicamento_id = data.get('medicamento_id')

        if not nombre or not medicamento_id:
            return jsonify({'ok': False, 'error': 'Faltan parámetros'}), 400

        # Normalizar nombre para verificación
        nombre_normalizado = nombre.lower()

        conn = get_db_connection()

        # Verificar que no exista un medicamento genérico con ese nombre
        existe = conn.execute(
            'SELECT id, nombre FROM medicamentos WHERE LOWER(nombre) = %s AND componente_activo_id IS NULL',
            (nombre_normalizado,)
        ).fetchone()

        if existe:
            conn.close()
            return jsonify({
                'ok': False,
                'error': f'Ya existe un componente activo con el nombre "{existe["nombre"]}"'
            }), 400

        # Crear nuevo medicamento genérico
        cursor = conn.execute(
            'INSERT INTO medicamentos (nombre, componente_activo_id) VALUES (%s, NULL)',
            (nombre.title(),)
        )
        nuevo_id = cursor.lastrowid

        # Asignar al medicamento original
        conn.execute(
            'UPDATE medicamentos SET componente_activo_id = %s WHERE id = %s',
            (nuevo_id, medicamento_id)
        )

        conn.commit()
        conn.close()

        return jsonify({
            'ok': True,
            'mensaje': f'Componente activo "{nombre}" creado y asignado correctamente',
            'componente_id': nuevo_id,
            'componente_nombre': nombre.title()
        })

    except Exception as e:
        print(f"Error creando componente activo: {e}")
        traceback.print_exc()
        return jsonify({'ok': False, 'error': str(e)}), 500


@app.route('/admin/sugerir-sintomas/guardar/<int:med_id>', methods=['POST'])
@admin_required
def guardar_sugerencias_sintomas(med_id):
    """Guarda los síntomas y diagnósticos seleccionados"""
    try:
        data = request.get_json()
        sintomas_ids = data.get('sintomas', [])  # Lista de IDs
        diagnosticos_ids = data.get('diagnosticos', [])  # Lista de IDs
        nuevos_sintomas = data.get('nuevos_sintomas', [])  # Lista de nombres
        nuevos_diagnosticos = data.get('nuevos_diagnosticos', [])  # Lista de {nombre, sintomas}

        conn = get_db_connection()

        # 1. Crear nuevos síntomas si es necesario
        sintomas_creados_ids = []
        for nombre_sintoma in nuevos_sintomas:
            # Verificar que no exista
            existe = conn.execute(
                'SELECT id FROM sintomas WHERE LOWER(nombre) = %s',
                (nombre_sintoma.lower(),)
            ).fetchone()

            if not existe:
                cursor = conn.execute(
                    'INSERT INTO sintomas (id, nombre, descripcion_lower) VALUES (DEFAULT, %s, %s)',
                    (nombre_sintoma.title(), nombre_sintoma.lower())
                )
                conn.commit()

                # El wrapper agrega RETURNING id automáticamente y lo guarda en lastrowid
                nuevo_id = cursor.lastrowid
                sintomas_creados_ids.append(nuevo_id)

        # 2. Crear nuevos diagnósticos si es necesario
        diagnosticos_creados_ids = []
        for diag_data in nuevos_diagnosticos:
            nombre_diag = diag_data['nombre']

            # Verificar que no exista
            existe = conn.execute(
                'SELECT id FROM diagnosticos WHERE LOWER(descripcion) = %s',
                (nombre_diag.lower(),)
            ).fetchone()

            if not existe:
                conn.execute(
                    'INSERT INTO diagnosticos (descripcion) VALUES (%s)',
                    (nombre_diag.title(),)
                )
                conn.commit()

                nuevo_id = conn.execute(
                    'SELECT id FROM diagnosticos WHERE LOWER(descripcion) = %s',
                    (nombre_diag.lower(),)
                ).fetchone()['id']

                diagnosticos_creados_ids.append(nuevo_id)

        # 3. Asignar síntomas al medicamento
        todos_sintomas_ids = sintomas_ids + sintomas_creados_ids

        for sintoma_id in todos_sintomas_ids:
            # Usar ON CONFLICT DO NOTHING para evitar errores de duplicados
            conn.execute(
                'INSERT INTO medicamento_sintoma (medicamento_id, sintoma_id) VALUES (%s, %s) ON CONFLICT DO NOTHING RETURNING medicamento_id',
                (med_id, sintoma_id)
            )

        # 4. Asignar diagnósticos al medicamento
        todos_diagnosticos_ids = diagnosticos_ids + diagnosticos_creados_ids

        for diag_id in todos_diagnosticos_ids:
            # Usar ON CONFLICT DO NOTHING para evitar errores de duplicados
            conn.execute(
                'INSERT INTO diagnostico_medicamento (medicamento_id, diagnostico_id) VALUES (%s, %s) ON CONFLICT DO NOTHING RETURNING medicamento_id',
                (med_id, diag_id)
            )

        conn.commit()

        # 5. Buscar siguiente medicamento pendiente
        siguiente = conn.execute("""
            SELECT m.id
            FROM medicamentos m
            LEFT JOIN medicamento_sintoma ms ON m.id = ms.medicamento_id
            WHERE ms.sintoma_id IS NULL AND m.id != %s
            ORDER BY
                CASE WHEN m.componente_activo_id IS NULL THEN 1 ELSE 0 END,
                (SELECT CASE WHEN p.precio > 0 THEN 0 ELSE 1 END FROM precios p WHERE p.medicamento_id = m.id LIMIT 1),
                m.nombre
            LIMIT 1
        """, (med_id,)).fetchone()

        conn.close()

        return jsonify({
            'ok': True,
            'siguiente_id': siguiente['id'] if siguiente else None,
            'sintomas_guardados': len(todos_sintomas_ids),
            'diagnosticos_guardados': len(todos_diagnosticos_ids)
        })

    except Exception as e:
        print(f"Error guardando síntomas: {e}")
        traceback.print_exc()
        return jsonify({'ok': False, 'error': str(e)}), 500


@app.route('/admin/sugerir-sintomas/guardar-texto-fuente/<int:med_id>', methods=['POST'])
@admin_required
def guardar_texto_fuente(med_id):
    """Guarda el texto fuente completo que se usó para detectar síntomas"""
    try:
        data = request.get_json()
        texto_fuente = data.get('texto_fuente', '').strip() if data else ''

        if not texto_fuente:
            return jsonify({'ok': False, 'error': 'Texto vacío'}), 400

        conn = get_db_connection()

        # Verificar que el medicamento existe
        medicamento = conn.execute(
            'SELECT id FROM medicamentos WHERE id = %s',
            (med_id,)
        ).fetchone()

        if not medicamento:
            conn.close()
            return jsonify({'ok': False, 'error': 'Medicamento no encontrado'}), 404

        # Actualizar texto_fuente
        conn.execute(
            'UPDATE medicamentos SET texto_fuente = %s WHERE id = %s',
            (texto_fuente, med_id)
        )
        conn.commit()
        conn.close()

        print(f"✅ [TEXTO FUENTE] Guardado para medicamento ID {med_id} ({len(texto_fuente)} caracteres)")

        return jsonify({
            'ok': True,
            'mensaje': 'Texto fuente guardado correctamente',
            'caracteres': len(texto_fuente)
        })

    except Exception as e:
        print(f"❌ Error al guardar texto_fuente: {e}")
        traceback.print_exc()
        return jsonify({'ok': False, 'error': str(e)}), 500


@app.route('/api/migrar-texto-fuente', methods=['GET'])
def migrar_texto_fuente():
    """ENDPOINT TEMPORAL: Agrega columna texto_fuente a tabla medicamentos si no existe"""
    try:
        import psycopg2
        database_url = os.getenv('DATABASE_URL')
        if database_url and database_url.startswith('postgres://'):
            database_url = database_url.replace('postgres://', 'postgresql://', 1)

        conn = psycopg2.connect(database_url)
        cursor = conn.cursor()

        # Verificar si la columna ya existe (usar LOWER para case-insensitive)
        cursor.execute("""
            SELECT column_name, table_name
            FROM information_schema.columns
            WHERE LOWER(table_name) = 'medicamentos'
            AND LOWER(column_name) = 'texto_fuente'
        """)
        existe = cursor.fetchone()

        if existe:
            conn.close()
            return jsonify({
                'ok': True,
                'mensaje': f'La columna texto_fuente ya existe en tabla {existe[1]}',
                'columna_agregada': False
            })

        # Primero, obtener el nombre REAL de la tabla (puede estar en mayúsculas)
        cursor.execute("""
            SELECT table_name
            FROM information_schema.tables
            WHERE table_schema = 'public'
            AND LOWER(table_name) = 'medicamentos'
        """)
        tabla_real = cursor.fetchone()

        if not tabla_real:
            conn.close()
            return jsonify({
                'ok': False,
                'error': 'No se encontró la tabla medicamentos en ningún formato (minúsculas/mayúsculas)'
            }), 404

        nombre_tabla = tabla_real[0]

        # Agregar columna texto_fuente usando el nombre real de la tabla con comillas
        cursor.execute(f"""
            ALTER TABLE "{nombre_tabla}"
            ADD COLUMN texto_fuente TEXT
        """)
        conn.commit()

        # Verificar que se agregó correctamente
        cursor.execute("""
            SELECT column_name, data_type, is_nullable
            FROM information_schema.columns
            WHERE LOWER(table_name) = 'medicamentos'
            AND LOWER(column_name) = 'texto_fuente'
        """)
        columna_info = cursor.fetchone()

        conn.close()

        return jsonify({
            'ok': True,
            'mensaje': f'Columna texto_fuente agregada exitosamente a tabla {nombre_tabla}',
            'columna_agregada': True,
            'tabla_real': nombre_tabla,
            'columna_info': {
                'nombre': columna_info[0],
                'tipo': columna_info[1],
                'nullable': columna_info[2]
            } if columna_info else None
        })

    except Exception as e:
        print(f"Error en migración texto_fuente: {e}")
        traceback.print_exc()
        return jsonify({'ok': False, 'error': str(e)}), 500


@app.route('/admin/diagnostico-sintomas', methods=['GET'])
@admin_required
def diagnostico_sintomas():
    """Endpoint temporal para diagnosticar medicamentos pendientes"""
    try:
        conn = get_db_connection()

        # 1. Total medicamentos
        total = conn.execute("SELECT COUNT(*) as total FROM medicamentos").fetchone()

        # 2. Medicamentos activos
        activos = conn.execute("SELECT COUNT(*) as total FROM medicamentos WHERE activo = '1'").fetchone()

        # 3. Con síntomas
        con_sintomas = conn.execute("""
            SELECT COUNT(DISTINCT m.id) as total
            FROM medicamentos m
            INNER JOIN medicamento_sintoma ms ON m.id = ms.medicamento_id
        """).fetchone()

        # 4. Sin síntomas (cualquier medicamento)
        sin_sintomas = conn.execute("""
            SELECT COUNT(DISTINCT m.id) as total
            FROM medicamentos m
            LEFT JOIN medicamento_sintoma ms ON m.id = ms.medicamento_id
            WHERE ms.sintoma_id IS NULL
        """).fetchone()

        # 5. Medicamentos SIN NINGÚN registro en medicamento_sintoma (ni una sola relación)
        sin_registros = conn.execute("""
            SELECT COUNT(DISTINCT m.id) as total
            FROM medicamentos m
            WHERE NOT EXISTS (
                SELECT 1 FROM medicamento_sintoma ms
                WHERE ms.medicamento_id = m.id
            )
        """).fetchone()

        # 5. Valores del campo activo
        valores_activo = conn.execute("""
            SELECT DISTINCT activo, COUNT(*) as cantidad
            FROM medicamentos
            GROUP BY activo
        """).fetchall()

        # 6. Medicamentos CON PRECIO (exhibibles en tienda)
        con_precio = conn.execute("""
            SELECT COUNT(DISTINCT m.id) as total
            FROM medicamentos m
            INNER JOIN precios p ON m.id = p.medicamento_id
            WHERE p.precio > 0
        """).fetchone()

        # 7. Medicamentos con precio Y con síntomas
        con_precio_y_sintomas = conn.execute("""
            SELECT COUNT(DISTINCT m.id) as total
            FROM medicamentos m
            INNER JOIN precios p ON m.id = p.medicamento_id
            INNER JOIN medicamento_sintoma ms ON m.id = ms.medicamento_id
            WHERE p.precio > 0
        """).fetchone()

        # 8. Medicamentos con precio SIN síntomas (PRIORITARIOS)
        con_precio_sin_sintomas = conn.execute("""
            SELECT COUNT(DISTINCT m.id) as total
            FROM medicamentos m
            INNER JOIN precios p ON m.id = p.medicamento_id
            LEFT JOIN medicamento_sintoma ms ON m.id = ms.medicamento_id
            WHERE p.precio > 0 AND ms.sintoma_id IS NULL
        """).fetchone()

        # 9. Primeros 5 con precio sin síntomas
        primeros_con_precio = conn.execute("""
            SELECT m.id, m.nombre, p.precio
            FROM medicamentos m
            INNER JOIN precios p ON m.id = p.medicamento_id
            LEFT JOIN medicamento_sintoma ms ON m.id = ms.medicamento_id
            WHERE p.precio > 0 AND ms.sintoma_id IS NULL
            ORDER BY p.precio DESC, m.nombre
            LIMIT 5
        """).fetchall()

        conn.close()

        return jsonify({
            'ok': True,
            'total_medicamentos': total['total'],
            'medicamentos_activos': activos['total'],
            'con_sintomas': con_sintomas['total'],
            'sin_sintomas_activos': sin_sintomas['total'],
            'sin_ningun_registro': sin_registros['total'],
            'con_precio': con_precio['total'],
            'con_precio_y_sintomas': con_precio_y_sintomas['total'],
            'con_precio_sin_sintomas': con_precio_sin_sintomas['total'],
            'valores_activo': [{'valor': v['activo'], 'cantidad': v['cantidad']} for v in valores_activo],
            'primeros_5_con_precio_sin_sintomas': [{'id': m['id'], 'nombre': m['nombre'], 'precio': m['precio']} for m in primeros_con_precio]
        })

    except Exception as e:
        print(f"Error en diagnóstico: {e}")
        traceback.print_exc()
        return jsonify({'ok': False, 'error': str(e)}), 500


