@app.route('/api/conductor/pico-placa')
def api_conductor_pico_placa():
    """Obtiene información de Pico y Placa para el conductor actual"""
    if 'usuario_id' not in session:
        return jsonify({'ok': False, 'error': 'No autenticado'}), 401

    from datetime import datetime

    try:
        conn = get_db_connection()

        # Obtener placa del conductor
        conductor = conn.execute("""
            SELECT placa FROM terceros WHERE id = %s
        """, (session['usuario_id'],)).fetchone()

        if not conductor or not conductor['placa']:
            conn.close()
            return jsonify({'ok': True, 'activo': False, 'mensaje': 'Sin placa registrada'})

        placa = conductor['placa']

        # Verificar si Pico y Placa está activo
        pico_placa_activo = conn.execute("""
            SELECT valor_booleano FROM parametros_sistema WHERE nombre = 'pico_placa_activo'
        """).fetchone()

        if not pico_placa_activo or not pico_placa_activo['valor_booleano']:
            conn.close()
            return jsonify({'ok': True, 'activo': False, 'mensaje': 'Pico y Placa no está activo en la ciudad'})

        # Obtener último dígito de la placa
        ultimo_digito = None
        for char in reversed(placa):
            if char.isdigit():
                ultimo_digito = char
                break

        if ultimo_digito is None:
            conn.close()
            return jsonify({'ok': True, 'activo': False, 'mensaje': 'No se pudo determinar el dígito de tu placa'})

        # Obtener horario de restricción
        hora_inicio_param = conn.execute("""
            SELECT valor_texto FROM parametros_sistema WHERE nombre = 'pico_placa_hora_inicio'
        """).fetchone()
        hora_fin_param = conn.execute("""
            SELECT valor_texto FROM parametros_sistema WHERE nombre = 'pico_placa_hora_fin'
        """).fetchone()

        hora_inicio_str = hora_inicio_param['valor_texto'] if hora_inicio_param else '06:00'
        hora_fin_str = hora_fin_param['valor_texto'] if hora_fin_param else '19:00'

        # Obtener configuración de días
        dias_config = {}
        dias_nombres = ['lunes', 'martes', 'miercoles', 'jueves', 'viernes']
        dias_display = ['Lunes', 'Martes', 'Miércoles', 'Jueves', 'Viernes']

        for i, dia in enumerate(dias_nombres):
            param = conn.execute("""
                SELECT valor_texto FROM parametros_sistema WHERE nombre = %s
            """, (f'pico_placa_{dia}',)).fetchone()
            if param and param['valor_texto']:
                digitos = [d.strip() for d in param['valor_texto'].split(',')]
                dias_config[i] = digitos

        # Encontrar qué día tiene restricción este conductor
        dia_restriccion = None
        dia_restriccion_nombre = None
        for dia_idx, digitos in dias_config.items():
            if ultimo_digito in digitos:
                dia_restriccion = dia_idx
                dia_restriccion_nombre = dias_display[dia_idx]
                break

        # Verificar estado actual
        ahora = datetime.now()
        dia_semana_actual = ahora.weekday()
        hora_actual = ahora.time()

        # Parsear horas
        try:
            hora_inicio = datetime.strptime(hora_inicio_str, '%H:%M').time()
            hora_fin = datetime.strptime(hora_fin_str, '%H:%M').time()
        except:
            hora_inicio = datetime.strptime('06:00', '%H:%M').time()
            hora_fin = datetime.strptime('19:00', '%H:%M').time()

        # Verificar si hoy es festivo
        fecha_hoy = ahora.date()
        es_festivo = conn.execute("""
            SELECT id FROM festivos WHERE fecha = %s AND activo = true
        """, (fecha_hoy,)).fetchone()

        conn.close()

        # Construir respuesta
        resultado = {
            'ok': True,
            'activo': True,
            'placa': placa,
            'ultimo_digito': ultimo_digito,
            'hora_inicio': hora_inicio_str,
            'hora_fin': hora_fin_str,
            'dia_restriccion': dia_restriccion_nombre,
            'es_hoy': False,
            'en_horario_restriccion': False,
            'es_fin_semana': dia_semana_actual >= 5,
            'es_festivo': es_festivo is not None,
            'tipo_alerta': 'info',
            'mensaje': ''
        }

        if dia_semana_actual >= 5:
            resultado['mensaje'] = f'🎉 Hoy es fin de semana, no hay Pico y Placa. Tu día de restricción es el {dia_restriccion_nombre}.'
            resultado['tipo_alerta'] = 'success'
        elif es_festivo:
            resultado['mensaje'] = f'🎉 Hoy es festivo, no hay Pico y Placa. Tu día de restricción es el {dia_restriccion_nombre}.'
            resultado['tipo_alerta'] = 'success'
        elif dia_restriccion is not None and dia_semana_actual == dia_restriccion:
            resultado['es_hoy'] = True
            if hora_inicio <= hora_actual <= hora_fin:
                resultado['en_horario_restriccion'] = True
                resultado['tipo_alerta'] = 'danger'
                resultado['mensaje'] = f'⚠️ ¡HOY TIENES PICO Y PLACA! Tu placa termina en {ultimo_digito}. Restricción hasta las {hora_fin_str}.'
            elif hora_actual < hora_inicio:
                resultado['tipo_alerta'] = 'warning'
                resultado['mensaje'] = f'⏰ Hoy tienes Pico y Placa desde las {hora_inicio_str} hasta las {hora_fin_str}. Placa termina en {ultimo_digito}.'
            else:
                resultado['tipo_alerta'] = 'success'
                resultado['mensaje'] = f'✅ Ya pasó el horario de Pico y Placa (terminó a las {hora_fin_str}). ¡Puedes circular libremente!'
        else:
            resultado['mensaje'] = f'✅ Hoy NO tienes Pico y Placa. Tu día de restricción es el {dia_restriccion_nombre} ({hora_inicio_str} - {hora_fin_str}).'
            resultado['tipo_alerta'] = 'success'

        return jsonify(resultado)

    except Exception as e:
        return jsonify({'ok': False, 'error': str(e)}), 500


@app.route('/api/conductor-cercano')
def api_conductor_cercano():
    """Busca el conductor más cercano activo para mostrar tiempo estimado de espera"""
    lat = request.args.get('lat', type=float)
    lon = request.args.get('lon', type=float)

    if not lat or not lon:
        return jsonify({'ok': False, 'error': 'Ubicación requerida'}), 400

    try:
        conn = get_db_connection()

        # 1. Buscar conductores LIBRES (conectados y sin viaje activo)
        conductores_libres = conn.execute("""
            SELECT t.id, t.nombre, t.ubicacion_lat, t.ubicacion_lon, 'libre' as estado_conductor, 0 as minutos_extra
            FROM terceros t
            WHERE t.estado_conexion = 'conectado'
              AND t.ultima_actividad > NOW() - INTERVAL '60 seconds'
              AND t.ubicacion_lat IS NOT NULL
              AND t.ubicacion_lon IS NOT NULL
              AND t.placa IS NOT NULL
              AND NOT EXISTS (
                  SELECT 1 FROM solicitudes_transporte s
                  WHERE s.conductor_id = t.id
                  AND s.estado IN ('aceptada', 'recogiendo', 'en_curso')
              )
        """).fetchall()

        # 2. Buscar conductores EN VIAJE que terminen pronto (< 30 min restantes)
        conductores_en_viaje = conn.execute("""
            SELECT t.id, t.nombre, s.destino_lat as ubicacion_lat, s.destino_lon as ubicacion_lon,
                   'en_viaje' as estado_conductor,
                   GREATEST(0, s.tiempo_estimado_minutos - EXTRACT(EPOCH FROM (NOW() - COALESCE(s.fecha_inicio_viaje, s.fecha_solicitud)))/60)::int as minutos_extra
            FROM terceros t
            JOIN solicitudes_transporte s ON s.conductor_id = t.id
            WHERE t.estado_conexion = 'conectado'
              AND t.ultima_actividad > NOW() - INTERVAL '60 seconds'
              AND t.placa IS NOT NULL
              AND s.estado = 'en_curso'
              AND s.destino_lat IS NOT NULL
              AND s.destino_lon IS NOT NULL
              AND (s.tiempo_estimado_minutos - EXTRACT(EPOCH FROM (NOW() - COALESCE(s.fecha_inicio_viaje, s.fecha_solicitud)))/60) < 30
        """).fetchall()

        # Combinar conductores libres y en viaje
        conductores = list(conductores_libres) + list(conductores_en_viaje)

        if not conductores:
            conn.close()
            return jsonify({
                'ok': True,
                'hay_conductores': False,
                'mensaje': 'Buscando conductor'
            })

        # Encontrar el conductor más cercano (considerando tiempo total: desplazamiento + minutos_extra si está en viaje)
        conductor_cercano = None
        menor_tiempo_total = float('inf')

        # Obtener velocidad según horario (pico/valle)
        velocidad_pico = obtener_parametro_transporte(conn, 'transporte_velocidad_pico', 10)
        velocidad_valle = obtener_parametro_transporte(conn, 'transporte_velocidad_valle', 17)
        hora_pico = es_hora_pico(conn)
        velocidad = velocidad_pico if hora_pico else velocidad_valle

        for c in conductores:
            dist = calcular_distancia(lat, lon, float(c['ubicacion_lat']), float(c['ubicacion_lon']))
            tiempo_desplazamiento = (dist / 1000 / velocidad) * 60  # en minutos
            minutos_extra = c['minutos_extra'] if c['minutos_extra'] else 0
            tiempo_total = tiempo_desplazamiento + minutos_extra

            if tiempo_total < menor_tiempo_total:
                menor_tiempo_total = tiempo_total
                conductor_cercano = c
                conductor_cercano_dist = dist

        # Obtener distancia real por calles: Waze → OSRM
        dist_data = obtener_distancia_con_fallback(
            float(conductor_cercano['ubicacion_lat']),
            float(conductor_cercano['ubicacion_lon']),
            lat, lon
        )

        if dist_data:
            distancia_km = dist_data['distancia_metros'] / 1000
        else:
            # Fallback a Haversine si todo falla
            distancia_km = conductor_cercano_dist / 1000

        # Calcular tiempo: (distancia / velocidad) * 60 minutos + minutos extra si está en viaje
        minutos_extra = conductor_cercano['minutos_extra'] if conductor_cercano['minutos_extra'] else 0
        tiempo_minutos = max(1, round((distancia_km / velocidad) * 60) + minutos_extra)

        conn.close()

        return jsonify({
            'ok': True,
            'hay_conductores': True,
            'conductores_activos': len(conductores),
            'tiempo_estimado_minutos': tiempo_minutos,
            'distancia_km': round(distancia_km, 1),
            'hora_pico': hora_pico
        })

    except Exception as e:
        return jsonify({'ok': False, 'error': str(e)}), 500


@app.route('/api/conductor/servicios-disponibles')
def api_conductor_servicios_disponibles():
    """Lista servicios pendientes ordenados por cercanía al conductor (OSRM)"""
    if 'usuario_id' not in session:
        return jsonify({'ok': False, 'error': 'No autenticado'}), 401

    lat = request.args.get('lat', type=float)
    lon = request.args.get('lon', type=float)

    if not lat or not lon:
        return jsonify({'ok': False, 'error': 'Ubicación requerida'}), 400

    try:
        conn = get_db_connection()

        # Obtener velocidad según hora pico/valle
        hora_pico = es_hora_pico(conn)
        param_vel = 'transporte_velocidad_pico' if hora_pico else 'transporte_velocidad_valle'
        vel_row = conn.execute("SELECT valor_numerico FROM parametros_sistema WHERE nombre = %s", (param_vel,)).fetchone()
        velocidad = float(vel_row['valor_numerico']) if vel_row and vel_row['valor_numerico'] else 25.0

        # Servicios inmediatos - traer más para pre-filtrar con Haversine
        rows = conn.execute("""
            SELECT s.id, s.origen_texto, s.destino_texto, s.origen_lat, s.origen_lon,
                   s.destino_lat, s.destino_lon, s.precio, s.fecha_solicitud,
                   s.distancia_km, s.tiempo_estimado_minutos,
                   t.nombre as usuario_nombre
            FROM solicitudes_transporte s
            JOIN terceros t ON s.tercero_id = t.id
            WHERE s.estado = 'pendiente' AND s.tipo_servicio = 'transporte'
              AND s.fecha_programada IS NULL
              AND s.origen_lat IS NOT NULL AND s.origen_lon IS NOT NULL
              AND s.destino_lat IS NOT NULL AND s.destino_lon IS NOT NULL
            ORDER BY s.fecha_solicitud DESC
            LIMIT 50
        """).fetchall()

        # Pre-filtrar con Haversine para obtener los 14 más cercanos
        candidatos = []
        for row in rows:
            dist_haversine = calcular_distancia(lat, lon, float(row['origen_lat']), float(row['origen_lon']))
            candidatos.append({'row': row, 'dist_pre': dist_haversine})

        candidatos.sort(key=lambda x: x['dist_pre'])
        candidatos = candidatos[:14]

        # Calcular distancia real a los 14 candidatos: Waze → OSRM
        servicios = []
        for c in candidatos:
            row = c['row']
            dist_data = obtener_distancia_con_fallback(lat, lon, float(row['origen_lat']), float(row['origen_lon']))
            if dist_data:
                dist_km = dist_data['distancia_metros'] / 1000
            else:
                dist_km = c['dist_pre'] / 1000

            tiempo_est = round((dist_km / velocidad) * 60)

            servicios.append({
                'id': row['id'],
                'origen_texto': row['origen_texto'],
                'destino_texto': row['destino_texto'],
                'origen_lat': float(row['origen_lat']),
                'origen_lon': float(row['origen_lon']),
                'destino_lat': float(row['destino_lat']),
                'destino_lon': float(row['destino_lon']),
                'tarifa': row['precio'],
                'usuario_nombre': row['usuario_nombre'],
                'distancia_conductor': round(dist_km * 1000),
                'distancia_conductor_texto': f"{dist_km:.1f} km · ~{tiempo_est} min",
                'distancia_recorrido_km': float(row['distancia_km']) if row['distancia_km'] else None,
                'tiempo_recorrido_min': row['tiempo_estimado_minutos']
            })

        servicios.sort(key=lambda x: x['distancia_conductor'])

        # Viajes programados - mismo proceso
        rows_prog = conn.execute("""
            SELECT s.id, s.origen_texto, s.destino_texto, s.origen_lat, s.origen_lon,
                   s.destino_lat, s.destino_lon, s.precio, s.fecha_programada,
                   s.distancia_km, s.tiempo_estimado_minutos,
                   t.nombre as usuario_nombre
            FROM solicitudes_transporte s
            JOIN terceros t ON s.tercero_id = t.id
            WHERE s.estado = 'pendiente' AND s.tipo_servicio = 'transporte'
              AND s.fecha_programada IS NOT NULL
              AND s.origen_lat IS NOT NULL AND s.origen_lon IS NOT NULL
              AND s.destino_lat IS NOT NULL AND s.destino_lon IS NOT NULL
            ORDER BY s.fecha_programada ASC
            LIMIT 50
        """).fetchall()

        # Pre-filtrar programados con Haversine
        candidatos_prog = []
        for row in rows_prog:
            dist_haversine = calcular_distancia(lat, lon, float(row['origen_lat']), float(row['origen_lon']))
            candidatos_prog.append({'row': row, 'dist_pre': dist_haversine})

        candidatos_prog.sort(key=lambda x: x['dist_pre'])
        candidatos_prog = candidatos_prog[:14]

        # Calcular distancia real a programados: Waze → OSRM
        programados = []
        for c in candidatos_prog:
            row = c['row']
            dist_data = obtener_distancia_con_fallback(lat, lon, float(row['origen_lat']), float(row['origen_lon']))
            if dist_data:
                dist_km = dist_data['distancia_metros'] / 1000
            else:
                dist_km = c['dist_pre'] / 1000

            tiempo_est = round((dist_km / velocidad) * 60)

            programados.append({
                'id': row['id'],
                'origen_texto': row['origen_texto'],
                'destino_texto': row['destino_texto'],
                'origen_lat': float(row['origen_lat']),
                'origen_lon': float(row['origen_lon']),
                'destino_lat': float(row['destino_lat']),
                'destino_lon': float(row['destino_lon']),
                'tarifa': row['precio'],
                'usuario_nombre': row['usuario_nombre'],
                'fecha_programada': row['fecha_programada'].isoformat() if row['fecha_programada'] else None,
                'distancia_conductor': round(dist_km * 1000),
                'distancia_conductor_texto': f"{dist_km:.1f} km · ~{tiempo_est} min",
                'distancia_recorrido_km': float(row['distancia_km']) if row['distancia_km'] else None,
                'tiempo_recorrido_min': row['tiempo_estimado_minutos']
            })

        programados.sort(key=lambda x: x['distancia_conductor'])

        conn.close()

        return jsonify({'ok': True, 'servicios': servicios, 'programados': programados, 'hora_pico': hora_pico})
    except Exception as e:
        return jsonify({'ok': False, 'error': str(e)}), 500


def validar_solapamiento_viajes(conn, conductor_id, nuevo_servicio):
    """
    Valida que el conductor pueda tomar un nuevo viaje sin solaparse con sus viajes existentes.
    Usa OSRM para calcular tiempo de traslado entre destino de viaje A y origen de viaje B.
    Aplica margen de seguridad de 10 minutos.

    Retorna: (puede_tomar: bool, mensaje_error: str o None)
    """
    from datetime import datetime, timedelta

    nuevo_origen_lat = float(nuevo_servicio['origen_lat'])
    nuevo_origen_lon = float(nuevo_servicio['origen_lon'])
    nuevo_fecha_programada = nuevo_servicio['fecha_programada']

    # Determinar hora del nuevo viaje
    if nuevo_fecha_programada:
        # Viaje programado
        hora_nuevo_viaje = nuevo_fecha_programada
    else:
        # Viaje inmediato - se considera NOW
        hora_nuevo_viaje = datetime.now()

    # Obtener velocidad según horario
    velocidad_pico = obtener_parametro_transporte(conn, 'transporte_velocidad_pico', 10)
    velocidad_valle = obtener_parametro_transporte(conn, 'transporte_velocidad_valle', 17)
    hora_pico = es_hora_pico(conn)
    velocidad = velocidad_pico if hora_pico else velocidad_valle

    MARGEN_SEGURIDAD_MINUTOS = 10

    viajes_a_verificar = []

    # 1. Buscar viaje en curso del conductor
    viaje_en_curso = conn.execute("""
        SELECT id, destino_lat, destino_lon, tiempo_estimado_minutos,
               fecha_inicio_viaje, fecha_solicitud, 'en_curso' as tipo
        FROM solicitudes_transporte
        WHERE conductor_id = %s AND estado = 'en_curso'
    """, (conductor_id,)).fetchone()

    if viaje_en_curso:
        viajes_a_verificar.append(viaje_en_curso)

    # 2. Buscar viaje en estado 'aceptada' o 'recogiendo' (viaje activo no en curso aún)
    viaje_activo = conn.execute("""
        SELECT id, destino_lat, destino_lon, tiempo_estimado_minutos,
               fecha_programada, fecha_solicitud, 'activo' as tipo
        FROM solicitudes_transporte
        WHERE conductor_id = %s AND estado IN ('aceptada', 'recogiendo')
          AND (fecha_programada IS NULL OR fecha_programada <= NOW() + INTERVAL '15 minutes')
    """, (conductor_id,)).fetchone()

    if viaje_activo:
        viajes_a_verificar.append(viaje_activo)

    # 3. Buscar viajes programados del conductor (futuros)
    viajes_programados = conn.execute("""
        SELECT id, origen_lat, origen_lon, destino_lat, destino_lon,
               tiempo_estimado_minutos, fecha_programada, 'programado' as tipo
        FROM solicitudes_transporte
        WHERE conductor_id = %s
          AND estado = 'aceptada'
          AND fecha_programada IS NOT NULL
          AND fecha_programada > NOW()
        ORDER BY fecha_programada ASC
    """, (conductor_id,)).fetchall()

    viajes_a_verificar.extend(viajes_programados)

    # Verificar cada viaje existente contra el nuevo
    for viaje in viajes_a_verificar:
        destino_lat = float(viaje['destino_lat'])
        destino_lon = float(viaje['destino_lon'])
        tiempo_estimado = viaje['tiempo_estimado_minutos'] or 30  # Default 30 min si no hay dato

        # Calcular hora de fin del viaje existente
        if viaje['tipo'] == 'en_curso':
            # Viaje en curso: hora_fin = fecha_inicio + tiempo_estimado
            fecha_inicio = viaje['fecha_inicio_viaje'] or viaje['fecha_solicitud']
            if fecha_inicio:
                hora_fin_viaje = fecha_inicio + timedelta(minutes=tiempo_estimado)
            else:
                hora_fin_viaje = datetime.now() + timedelta(minutes=tiempo_estimado)
        elif viaje['tipo'] == 'activo':
            # Viaje activo (aceptado/recogiendo): estimamos que terminará pronto + tiempo de viaje
            hora_fin_viaje = datetime.now() + timedelta(minutes=tiempo_estimado + 10)  # +10 para recogida
        else:
            # Viaje programado: hora_fin = fecha_programada + tiempo_estimado
            hora_fin_viaje = viaje['fecha_programada'] + timedelta(minutes=tiempo_estimado)

        # Calcular tiempo de traslado: Waze → OSRM (destino viaje A → origen nuevo viaje)
        dist_data = obtener_distancia_con_fallback(destino_lat, destino_lon, nuevo_origen_lat, nuevo_origen_lon)

        if dist_data:
            distancia_km = dist_data['distancia_metros'] / 1000
        else:
            # Fallback a Haversine si todo falla
            distancia_metros = calcular_distancia(destino_lat, destino_lon, nuevo_origen_lat, nuevo_origen_lon)
            distancia_km = distancia_metros / 1000

        # Tiempo de traslado en minutos = (distancia / velocidad) * 60
        tiempo_traslado_min = (distancia_km / velocidad) * 60

        # Hora en que el conductor estaría disponible para el nuevo viaje
        hora_disponible = hora_fin_viaje + timedelta(minutes=tiempo_traslado_min + MARGEN_SEGURIDAD_MINUTOS)

        # Verificar solapamiento
        if hora_disponible > hora_nuevo_viaje:
            # Hay solapamiento
            diferencia_min = int((hora_disponible - hora_nuevo_viaje).total_seconds() / 60)

            if viaje['tipo'] == 'programado':
                # Si es viaje programado contra programado, verificar también al revés
                # (el nuevo viaje podría terminar cuando empieza el programado)
                if nuevo_fecha_programada:
                    nuevo_tiempo_estimado = nuevo_servicio.get('tiempo_estimado_minutos', 30)
                    hora_fin_nuevo = nuevo_fecha_programada + timedelta(minutes=nuevo_tiempo_estimado)

                    # Tiempo de traslado inverso (destino nuevo → origen programado)
                    nuevo_destino_lat = float(nuevo_servicio['destino_lat'])
                    nuevo_destino_lon = float(nuevo_servicio['destino_lon'])
                    origen_prog_lat = float(viaje['origen_lat'])
                    origen_prog_lon = float(viaje['origen_lon'])

                    dist_inv = obtener_distancia_con_fallback(nuevo_destino_lat, nuevo_destino_lon, origen_prog_lat, origen_prog_lon)
                    if dist_inv:
                        dist_inv_km = dist_inv['distancia_metros'] / 1000
                    else:
                        dist_inv_km = calcular_distancia(nuevo_destino_lat, nuevo_destino_lon, origen_prog_lat, origen_prog_lon) / 1000

                    tiempo_traslado_inv = (dist_inv_km / velocidad) * 60
                    hora_disponible_inv = hora_fin_nuevo + timedelta(minutes=tiempo_traslado_inv + MARGEN_SEGURIDAD_MINUTOS)

                    if hora_disponible_inv > viaje['fecha_programada']:
                        return (False, f"Este viaje terminaría muy tarde para tu viaje programado de las {viaje['fecha_programada'].strftime('%H:%M')}")

            return (False, f"No podrías llegar a tiempo. Estarías disponible en {diferencia_min} minutos después de la hora solicitada.")

    return (True, None)


def validar_solapamiento_pasajero(conn, tercero_id, fecha_programada_str, tiempo_estimado_minutos):
    """
    Valida que el pasajero pueda solicitar un nuevo viaje sin solaparse con viajes existentes.

    - Viaje inmediato: no puede tener viajes activos
    - Viaje programado: no puede solaparse con otros viajes programados

    Retorna: (puede_solicitar: bool, mensaje_error: str o None)
    """
    from datetime import datetime, timedelta

    # 1. Verificar si tiene viaje activo (pendiente, aceptada, recogiendo, en_curso)
    viaje_activo = conn.execute("""
        SELECT id, estado, origen_texto, destino_texto, fecha_programada
        FROM solicitudes_transporte
        WHERE tercero_id = %s
          AND estado IN ('pendiente', 'aceptada', 'recogiendo', 'en_curso')
          AND (fecha_programada IS NULL OR fecha_programada <= NOW() + INTERVAL '15 minutes')
        LIMIT 1
    """, (tercero_id,)).fetchone()

    # Si es viaje inmediato (no programado)
    if not fecha_programada_str:
        if viaje_activo:
            return (False, f"Ya tienes un viaje activo en curso. Complétalo antes de solicitar otro.")
        return (True, None)

    # Es viaje programado - parsear fecha
    try:
        fecha_programada = datetime.fromisoformat(fecha_programada_str.replace('Z', '+00:00'))
        if fecha_programada.tzinfo:
            fecha_programada = fecha_programada.replace(tzinfo=None)
    except:
        fecha_programada = datetime.strptime(fecha_programada_str, '%Y-%m-%d %H:%M:%S')

    tiempo_nuevo = tiempo_estimado_minutos or 30
    hora_fin_nuevo = fecha_programada + timedelta(minutes=tiempo_nuevo)

    # 2. Verificar solapamiento con viajes programados existentes
    viajes_programados = conn.execute("""
        SELECT id, fecha_programada, tiempo_estimado_minutos, origen_texto, destino_texto
        FROM solicitudes_transporte
        WHERE tercero_id = %s
          AND estado IN ('pendiente', 'aceptada')
          AND fecha_programada IS NOT NULL
          AND fecha_programada > NOW()
    """, (tercero_id,)).fetchall()

    for viaje in viajes_programados:
        viaje_inicio = viaje['fecha_programada']
        viaje_tiempo = viaje['tiempo_estimado_minutos'] or 30
        viaje_fin = viaje_inicio + timedelta(minutes=viaje_tiempo)

        # Margen de 5 minutos entre viajes (pasajero puede hacer varias vueltas)
        MARGEN_MINUTOS = 5

        # Verificar solapamiento: nuevo viaje no puede empezar antes de que termine el existente + margen
        # ni terminar después de que empiece el existente - margen
        if not (hora_fin_nuevo + timedelta(minutes=MARGEN_MINUTOS) <= viaje_inicio or
                fecha_programada >= viaje_fin + timedelta(minutes=MARGEN_MINUTOS)):
            return (False, f"Ya tienes un viaje programado a las {viaje_inicio.strftime('%H:%M')} ({viaje['destino_texto']}). Los viajes no pueden solaparse.")

    return (True, None)


def validar_pico_placa(conn, placa, fecha_hora_viaje=None):
    """
    Valida si un vehículo puede circular según las restricciones de Pico y Placa.

    Args:
        conn: Conexión a BD
        placa: Placa del vehículo (ej: "ABC123")
        fecha_hora_viaje: datetime del viaje (None = ahora)

    Retorna: (puede_circular: bool, mensaje_error: str o None)
    """
    from datetime import datetime

    # Verificar si Pico y Placa está activo
    pico_placa_activo = conn.execute("""
        SELECT valor_booleano FROM parametros_sistema WHERE nombre = 'pico_placa_activo'
    """).fetchone()

    if not pico_placa_activo or not pico_placa_activo['valor_booleano']:
        return (True, None)  # Pico y Placa no está activo

    # Obtener fecha/hora del viaje
    if fecha_hora_viaje is None:
        fecha_hora_viaje = datetime.now()
    elif isinstance(fecha_hora_viaje, str):
        try:
            fecha_hora_viaje = datetime.fromisoformat(fecha_hora_viaje.replace('Z', '+00:00'))
            if fecha_hora_viaje.tzinfo:
                fecha_hora_viaje = fecha_hora_viaje.replace(tzinfo=None)
        except:
            fecha_hora_viaje = datetime.now()

    # Sábado (5) y Domingo (6) no tienen restricción
    dia_semana = fecha_hora_viaje.weekday()
    if dia_semana >= 5:
        return (True, None)

    # Verificar si es día festivo
    fecha_viaje = fecha_hora_viaje.date()
    es_festivo = conn.execute("""
        SELECT id FROM festivos WHERE fecha = %s AND activo = true
    """, (fecha_viaje,)).fetchone()

    if es_festivo:
        return (True, None)  # Festivos no tienen restricción

    # Obtener horario de restricción
    hora_inicio_param = conn.execute("""
        SELECT valor_texto FROM parametros_sistema WHERE nombre = 'pico_placa_hora_inicio'
    """).fetchone()
    hora_fin_param = conn.execute("""
        SELECT valor_texto FROM parametros_sistema WHERE nombre = 'pico_placa_hora_fin'
    """).fetchone()

    hora_inicio_str = hora_inicio_param['valor_texto'] if hora_inicio_param else '06:00'
    hora_fin_str = hora_fin_param['valor_texto'] if hora_fin_param else '19:00'

    # Parsear horas
    try:
        hora_inicio = datetime.strptime(hora_inicio_str, '%H:%M').time()
        hora_fin = datetime.strptime(hora_fin_str, '%H:%M').time()
    except:
        hora_inicio = datetime.strptime('06:00', '%H:%M').time()
        hora_fin = datetime.strptime('19:00', '%H:%M').time()

    # Verificar si está dentro del horario de restricción
    hora_viaje = fecha_hora_viaje.time()
    if not (hora_inicio <= hora_viaje <= hora_fin):
        return (True, None)  # Fuera del horario de restricción

    # Obtener último dígito de la placa
    if not placa:
        return (True, None)  # Sin placa, no se puede validar

    ultimo_digito = None
    for char in reversed(placa):
        if char.isdigit():
            ultimo_digito = char
            break

    if ultimo_digito is None:
        return (True, None)  # No se encontró dígito en la placa

    # Obtener dígitos restringidos para el día
    dias_param = ['pico_placa_lunes', 'pico_placa_martes', 'pico_placa_miercoles',
                  'pico_placa_jueves', 'pico_placa_viernes']
    dia_param = dias_param[dia_semana]

    digitos_restringidos_param = conn.execute("""
        SELECT valor_texto FROM parametros_sistema WHERE nombre = %s
    """, (dia_param,)).fetchone()

    if not digitos_restringidos_param or not digitos_restringidos_param['valor_texto']:
        return (True, None)  # No hay restricción configurada para este día

    # Parsear dígitos restringidos (ej: "1,2" -> ['1', '2'])
    digitos_restringidos = [d.strip() for d in digitos_restringidos_param['valor_texto'].split(',')]

    # Verificar si el último dígito está restringido
    if ultimo_digito in digitos_restringidos:
        dias_nombres = ['lunes', 'martes', 'miércoles', 'jueves', 'viernes']
        return (False, f"Tu vehículo tiene Pico y Placa hoy ({dias_nombres[dia_semana]}). Placas terminadas en {', '.join(digitos_restringidos)} no pueden circular entre {hora_inicio_str} y {hora_fin_str}.")

    return (True, None)


@app.route('/api/conductor/tomar-servicio/<int:servicio_id>', methods=['POST'])
def api_conductor_tomar_servicio(servicio_id):
    """Conductor toma un servicio"""
    if 'usuario_id' not in session:
        return jsonify({'ok': False, 'error': 'No autenticado'}), 401

    try:
        conn = get_db_connection()

        # Verificar que el servicio esté pendiente
        servicio = conn.execute("""
            SELECT s.*, t.nombre as usuario_nombre, t.push_token as usuario_push_token
            FROM solicitudes_transporte s
            JOIN terceros t ON s.tercero_id = t.id
            WHERE s.id = %s AND s.estado = 'pendiente'
        """, (servicio_id,)).fetchone()

        if not servicio:
            conn.close()
            return jsonify({'ok': False, 'error': 'Servicio no disponible'}), 400

        # Validar que no haya solapamiento con viajes existentes del conductor
        puede_tomar, mensaje_error = validar_solapamiento_viajes(conn, session['usuario_id'], servicio)
        if not puede_tomar:
            conn.close()
            return jsonify({'ok': False, 'error': mensaje_error}), 400

        # Obtener datos del conductor
        conductor = conn.execute("""
            SELECT nombre, telefono, placa, color_vehiculo, marca_vehiculo, modelo_vehiculo
            FROM terceros WHERE id = %s
        """, (session['usuario_id'],)).fetchone()

        # Validar Pico y Placa
        fecha_viaje = servicio['fecha_programada'] if servicio['fecha_programada'] else None
        puede_circular, mensaje_pico_placa = validar_pico_placa(conn, conductor['placa'], fecha_viaje)
        if not puede_circular:
            conn.close()
            return jsonify({'ok': False, 'error': mensaje_pico_placa}), 400

        # Obtener ubicación del conductor si fue enviada
        data = request.get_json() or {}
        cond_lat = data.get('conductor_lat')
        cond_lon = data.get('conductor_lon')

        # Actualizar servicio
        conn.execute("""
            UPDATE solicitudes_transporte
            SET estado = 'aceptada', conductor_id = %s,
                conductor_placa = %s, conductor_color = %s,
                conductor_marca = %s, conductor_modelo = %s,
                conductor_lat = %s, conductor_lon = %s
            WHERE id = %s
        """, (session['usuario_id'], conductor['placa'], conductor['color_vehiculo'],
              conductor['marca_vehiculo'], conductor['modelo_vehiculo'],
              cond_lat, cond_lon, servicio_id))

        # Auto-conectar al conductor cuando toma un servicio
        conn.execute("""
            UPDATE terceros
            SET estado_conexion = 'conectado', ultima_actividad = NOW()
            WHERE id = %s
        """, (session['usuario_id'],))

        conn.commit()
        conn.close()

        # Enviar push notification al pasajero
        if servicio['usuario_push_token']:
            es_programado = servicio['fecha_programada'] is not None
            if es_programado:
                titulo = "Un conductor aceptó tu viaje"
                mensaje = f"{conductor['nombre']} ({conductor['placa']}) tomó tu viaje programado"
            else:
                titulo = "Conductor en camino"
                mensaje = f"{conductor['nombre']} va en camino a recogerte"
            enviar_push_notification(servicio['usuario_push_token'], titulo, mensaje, '/servicios')

        return jsonify({
            'ok': True,
            'viaje': {
                'id': servicio_id,
                'estado': 'aceptada',
                'origen_texto': servicio['origen_texto'],
                'destino_texto': servicio['destino_texto'],
                'origen_lat': float(servicio['origen_lat']),
                'origen_lon': float(servicio['origen_lon']),
                'destino_lat': float(servicio['destino_lat']),
                'destino_lon': float(servicio['destino_lon']),
                'tarifa': servicio['precio'],
                'usuario_nombre': servicio['usuario_nombre'],
                'fecha_programada': servicio['fecha_programada'].isoformat() if servicio['fecha_programada'] else None
            }
        })
    except Exception as e:
        return jsonify({'ok': False, 'error': str(e)}), 500


@app.route('/api/conductor/viaje-activo')
def api_conductor_viaje_activo():
    """Obtiene el viaje activo del conductor (si tiene uno)"""
    if 'usuario_id' not in session:
        return jsonify({'ok': False, 'error': 'No autenticado'}), 401

    try:
        conn = get_db_connection()
        # Solo viajes inmediatos O programados cuya hora ya llegó (con 15 min de anticipación)
        viaje = conn.execute("""
            SELECT s.*, t.nombre as usuario_nombre
            FROM solicitudes_transporte s
            JOIN terceros t ON s.tercero_id = t.id
            WHERE s.conductor_id = %s AND s.estado IN ('aceptada', 'recogiendo', 'en_curso')
              AND (s.fecha_programada IS NULL OR s.fecha_programada <= NOW() + INTERVAL '15 minutes')
            LIMIT 1
        """, (session['usuario_id'],)).fetchone()
        conn.close()

        if viaje:
            return jsonify({
                'ok': True,
                'viaje': {
                    'id': viaje['id'],
                    'estado': viaje['estado'],
                    'origen_texto': viaje['origen_texto'],
                    'destino_texto': viaje['destino_texto'],
                    'origen_lat': float(viaje['origen_lat']),
                    'origen_lon': float(viaje['origen_lon']),
                    'destino_lat': float(viaje['destino_lat']),
                    'destino_lon': float(viaje['destino_lon']),
                    'tarifa': viaje['precio'],
                    'usuario_nombre': viaje['usuario_nombre'],
                    'tipo_servicio': viaje['tipo_servicio']
                }
            })
        return jsonify({'ok': True, 'viaje': None})
    except Exception as e:
        return jsonify({'ok': False, 'error': str(e)}), 500


@app.route('/api/viaje/<int:viaje_id>/ruta')
def api_viaje_ruta(viaje_id):
    """Retorna ruta completa del viaje en dos tramos: conductor→recogida y recogida→destino"""
    if 'usuario_id' not in session:
        return jsonify({'ok': False, 'error': 'No autenticado'}), 401

    try:
        conn = get_db_connection()
        viaje = conn.execute("""
            SELECT id, estado, origen_lat, origen_lon, destino_lat, destino_lon,
                   conductor_lat, conductor_lon
            FROM solicitudes_transporte
            WHERE id = %s AND conductor_id = %s
        """, (viaje_id, session['usuario_id'])).fetchone()

        if not viaje:
            conn.close()
            return jsonify({'ok': False, 'error': 'Viaje no encontrado'}), 404

        resultado = {'ok': True, 'leg1': None, 'leg2': None, 'camaras': [], 'peajes': []}
        geometria_completa = []

        # Tramo 1: Conductor → Recogida (solo si aún no recogió al pasajero)
        if viaje['estado'] in ('aceptada', 'recogiendo') and viaje['conductor_lat'] and viaje['conductor_lon']:
            cond_lat = float(viaje['conductor_lat'])
            cond_lon = float(viaje['conductor_lon'])
            orig_lat = float(viaje['origen_lat'])
            orig_lon = float(viaje['origen_lon'])
            print(f"🚗 Tramo 1: conductor ({cond_lat},{cond_lon}) → recogida ({orig_lat},{orig_lon})")
            leg1 = obtener_ruta_con_fallback(cond_lat, cond_lon, orig_lat, orig_lon, conn)
            if leg1:
                resultado['leg1'] = leg1
                geometria_completa.extend(leg1['geometria'])

        # Tramo 2: Origen → Destino
        # Si el conductor se desvió (desde_actual=1) y el viaje está en curso,
        # usar posición actual del conductor como origen
        desde_actual = request.args.get('desde_actual') == '1'
        if desde_actual and viaje['estado'] == 'en_curso' and viaje['conductor_lat'] and viaje['conductor_lon']:
            orig_lat = float(viaje['conductor_lat'])
            orig_lon = float(viaje['conductor_lon'])
            print(f"🔄 Recalculando desde posición actual del conductor ({orig_lat},{orig_lon})")
        else:
            orig_lat = float(viaje['origen_lat'])
            orig_lon = float(viaje['origen_lon'])
        dest_lat = float(viaje['destino_lat'])
        dest_lon = float(viaje['destino_lon'])
        print(f"🚗 Tramo 2: ({orig_lat},{orig_lon}) → destino ({dest_lat},{dest_lon})")
        leg2 = obtener_ruta_con_fallback(orig_lat, orig_lon, dest_lat, dest_lon, conn)
        if leg2:
            resultado['leg2'] = leg2
            geometria_completa.extend(leg2['geometria'])

        # Detectar cámaras y peajes en geometría combinada
        if geometria_completa:
            resultado['camaras'] = detectar_camaras_en_ruta(geometria_completa, conn)
            resultado['peajes'] = detectar_peajes_en_ruta(geometria_completa, conn)

        # Calcular distancia total y velocidad para estimación de tiempo
        distancia_total = 0
        if resultado['leg1'] and resultado['leg1'].get('distancia_metros'):
            distancia_total += resultado['leg1']['distancia_metros']
        if resultado['leg2'] and resultado['leg2'].get('distancia_metros'):
            distancia_total += resultado['leg2']['distancia_metros']

        hora_pico = es_hora_pico(conn)
        velocidad_kmh = obtener_parametro_transporte(conn, 'transporte_velocidad_pico', 10) if hora_pico else obtener_parametro_transporte(conn, 'transporte_velocidad_valle', 17)
        resultado['distancia_total_metros'] = round(distancia_total)
        resultado['velocidad_kmh'] = velocidad_kmh
        resultado['es_hora_pico'] = hora_pico

        conn.close()
        return jsonify(resultado)
    except Exception as e:
        print(f"Error en /api/viaje/{viaje_id}/ruta: {e}")
        import traceback
        traceback.print_exc()
        return jsonify({'ok': False, 'error': str(e)}), 500


@app.route('/api/conductor/mis-programados')
def api_conductor_mis_programados():
    """Retorna los viajes programados que el conductor ha aceptado"""
    if 'usuario_id' not in session:
        return jsonify({'ok': False, 'error': 'No autenticado'}), 401

    try:
        conn = get_db_connection()
        viajes = conn.execute("""
            SELECT s.id, s.origen_texto, s.destino_texto, s.precio, s.fecha_programada,
                   t.nombre as usuario_nombre
            FROM solicitudes_transporte s
            JOIN terceros t ON s.tercero_id = t.id
            WHERE s.conductor_id = %s
              AND s.estado = 'aceptada'
              AND s.fecha_programada IS NOT NULL
              AND s.fecha_programada > NOW() + INTERVAL '15 minutes'
            ORDER BY s.fecha_programada ASC
        """, (session['usuario_id'],)).fetchall()
        conn.close()

        resultado = []
        for v in viajes:
            resultado.append({
                'id': v['id'],
                'origen_texto': v['origen_texto'],
                'destino_texto': v['destino_texto'],
                'precio': float(v['precio']) if v['precio'] else 0,
                'fecha_programada': v['fecha_programada'].isoformat() if v['fecha_programada'] else None,
                'usuario_nombre': v['usuario_nombre']
            })

        return jsonify({'ok': True, 'viajes': resultado})
    except Exception as e:
        return jsonify({'ok': False, 'error': str(e)}), 500


@app.route('/api/guardar-push-token', methods=['POST'])
def api_guardar_push_token():
    """Guarda el token de push notifications del usuario"""
    try:
        data = request.get_json() or {}
        token = data.get('token')
        telefono = data.get('telefono', '').strip()

        if not token:
            return jsonify({'ok': False, 'error': 'Token requerido'}), 400

        conn = get_db_connection()

        # Guardar en USUARIOS por dispositivo_id (siempre existe)
        if 'dispositivo_id' in session:
            conn.execute('UPDATE "USUARIOS" SET push_token = %s WHERE dispositivo_id = %s',
                         (token, session['dispositivo_id']))

        # Guardar en terceros - buscar por teléfono (más confiable que usuario_id)
        tercero_ok = False
        # 1) Teléfono enviado desde el frontend
        if telefono:
            cur = conn.execute("UPDATE terceros SET push_token = %s WHERE telefono = %s RETURNING id",
                         (token, telefono))
            if cur.fetchone():
                tercero_ok = True
        # 2) Teléfono en sesión (de interacción previa)
        if not tercero_ok and session.get('telefono'):
            cur = conn.execute("UPDATE terceros SET push_token = %s WHERE telefono = %s RETURNING id",
                         (token, session['telefono']))
            if cur.fetchone():
                tercero_ok = True
        # 3) Fallback: usuario_id en sesión (funciona si coincide con terceros.id)
        if not tercero_ok and 'usuario_id' in session:
            conn.execute("UPDATE terceros SET push_token = %s WHERE id = %s",
                         (token, session['usuario_id']))

        conn.commit()
        conn.close()

        return jsonify({'ok': True, 'tercero': tercero_ok})
    except Exception as e:
        return jsonify({'ok': False, 'error': str(e)}), 500


@app.route('/api/admin/test-push', methods=['POST'])
def api_admin_test_push():
    """Envía una notificación push de prueba"""
    if session.get('rol') != 'Administrador':
        return jsonify({'ok': False, 'error': 'Solo admin'}), 403
    try:
        data = request.get_json() or {}
        tercero_id = data.get('tercero_id')
        titulo = data.get('titulo', 'Prueba TUC TUC')
        mensaje = data.get('mensaje', 'Esta es una notificación de prueba')
        url = data.get('url', '/servicios')

        conn = get_db_connection()

        # Buscar push_token en terceros
        tercero = conn.execute("SELECT nombre, push_token, telefono FROM terceros WHERE id = %s",
                               (tercero_id,)).fetchone()
        if not tercero:
            conn.close()
            return jsonify({'ok': False, 'error': f'Tercero {tercero_id} no encontrado'}), 404

        push_token = tercero['push_token']

        # Si terceros no tiene token, buscar en USUARIOS por teléfono
        if not push_token and tercero['telefono']:
            usuario = conn.execute(
                'SELECT push_token FROM "USUARIOS" WHERE push_token IS NOT NULL ORDER BY id DESC LIMIT 1'
            ).fetchone()

        conn.close()

        if not push_token:
            return jsonify({'ok': False, 'error': f'{tercero["nombre"]} no tiene push_token'}), 400

        resultado = enviar_push_notification(push_token, titulo, mensaje, url)
        return jsonify({'ok': resultado, 'nombre': tercero['nombre']})
    except Exception as e:
        return jsonify({'ok': False, 'error': str(e)}), 500


@app.route('/api/conductor/llegue/<int:servicio_id>', methods=['POST'])
def api_conductor_llegue(servicio_id):
    """Conductor indica que llegó al punto de recogida"""
    if 'usuario_id' not in session:
        return jsonify({'ok': False, 'error': 'No autenticado'}), 401

    try:
        conn = get_db_connection()

        # Obtener datos del pasajero para push notification
        servicio = conn.execute("""
            SELECT s.tercero_id, t.push_token, t.nombre as pasajero_nombre
            FROM solicitudes_transporte s
            JOIN terceros t ON s.tercero_id = t.id
            WHERE s.id = %s AND s.conductor_id = %s
        """, (servicio_id, session['usuario_id'])).fetchone()

        conn.execute("""
            UPDATE solicitudes_transporte SET estado = 'recogiendo'
            WHERE id = %s AND conductor_id = %s AND estado = 'aceptada'
        """, (servicio_id, session['usuario_id']))
        conn.commit()
        conn.close()

        # Enviar push notification al pasajero
        if servicio and servicio['push_token']:
            enviar_push_notification(
                servicio['push_token'],
                "Tu conductor llegó",
                "Sal a encontrarte con tu conductor",
                '/servicios'
            )

        return jsonify({'ok': True})
    except Exception as e:
        return jsonify({'ok': False, 'error': str(e)}), 500


