def obtener_parametro_transporte(conn, nombre, valor_defecto):
    """Obtiene un parámetro de transporte de la BD o retorna el valor por defecto"""
    try:
        row = conn.execute("""
            SELECT valor_numerico, valor_texto, tipo
            FROM parametros_sistema
            WHERE nombre = %s
        """, (nombre,)).fetchone()

        if row:
            if row['tipo'] == 'numerico':
                return float(row['valor_numerico']) if row['valor_numerico'] is not None else valor_defecto
            elif row['tipo'] == 'texto':
                return row['valor_texto'] if row['valor_texto'] is not None else valor_defecto
        return valor_defecto
    except:
        return valor_defecto


def es_hora_pico(conn, fecha_hora=None):
    """Determina si una fecha/hora es hora pico según los parámetros configurados.
    Si fecha_hora es None, usa la hora actual."""
    from datetime import datetime

    ahora = fecha_hora if fecha_hora else datetime.now()
    dia_semana = ahora.weekday()  # 0=Lunes, 6=Domingo
    hora_actual = ahora.strftime('%H:%M')

    # Domingo = siempre valle
    if dia_semana == 6:
        return False

    # Verificar si es festivo (usar la tabla de festivos existente)
    try:
        fecha_evaluar = ahora.strftime('%Y-%m-%d')
        festivo = conn.execute("""
            SELECT id FROM festivos WHERE fecha = %s
        """, (fecha_evaluar,)).fetchone()
        if festivo:
            return False  # Festivo = hora valle
    except:
        pass

    # Sábado
    if dia_semana == 5:
        pico_am_inicio = obtener_parametro_transporte(conn, 'transporte_pico_sab_am_inicio', '07:00')
        pico_am_fin = obtener_parametro_transporte(conn, 'transporte_pico_sab_am_fin', '09:00')
        pico_pm_inicio = obtener_parametro_transporte(conn, 'transporte_pico_sab_pm_inicio', '12:00')
        pico_pm_fin = obtener_parametro_transporte(conn, 'transporte_pico_sab_pm_fin', '15:30')
    else:
        # Lunes a Viernes
        pico_am_inicio = obtener_parametro_transporte(conn, 'transporte_pico_lv_am_inicio', '07:00')
        pico_am_fin = obtener_parametro_transporte(conn, 'transporte_pico_lv_am_fin', '08:30')
        pico_pm_inicio = obtener_parametro_transporte(conn, 'transporte_pico_lv_pm_inicio', '16:30')
        pico_pm_fin = obtener_parametro_transporte(conn, 'transporte_pico_lv_pm_fin', '19:30')

    # Verificar si está en rango de hora pico
    if pico_am_inicio <= hora_actual <= pico_am_fin:
        return True
    if pico_pm_inicio <= hora_actual <= pico_pm_fin:
        return True

    return False


@app.route('/api/calcular-tarifa', methods=['POST'])
def api_calcular_tarifa():
    """
    Calcula tarifa estimada basada en distancia o horas
    Usa parámetros configurables desde admin_parametros

    Body JSON:
    {
        "tipo_servicio": "transporte" | "acompanamiento",
        "distancia_km": 5.2,  # Para transporte
        "horas_acompanamiento": 3,  # Para acompañamiento
        "origen_lat": 3.45,  # Opcional, para detectar peajes
        "origen_lon": -76.53,
        "destino_lat": 3.48,
        "destino_lon": -76.55
    }
    """
    try:
        data = request.get_json()
        tipo_servicio = data.get('tipo_servicio')
        distancia_km = data.get('distancia_km', 0)
        horas = data.get('horas_acompanamiento')
        fecha_programada_str = data.get('fecha_programada')

        # Coordenadas para detectar peajes
        origen_lat = data.get('origen_lat')
        origen_lon = data.get('origen_lon')
        destino_lat = data.get('destino_lat')
        destino_lon = data.get('destino_lon')

        conn = get_db_connection()

        # Detectar peajes si tenemos coordenadas
        peajes_detectados = []
        total_peajes = 0
        geometria_ruta = None

        if origen_lat and origen_lon and destino_lat and destino_lon:
            # Obtener ruta con geometría: grafo → Waze → OSRM
            ruta_data = obtener_ruta_con_fallback(origen_lat, origen_lon, destino_lat, destino_lon, conn)
            if ruta_data and 'geometria' in ruta_data:
                geometria_ruta = ruta_data['geometria']
                peajes_detectados = detectar_peajes_en_ruta(geometria_ruta, conn)
                total_peajes = sum(p['tarifa'] for p in peajes_detectados)

                # Segmentos ya guardados dentro de obtener_ruta_con_fallback

        if tipo_servicio == 'transporte':
            # Obtener parámetros configurables
            tarifa_base = obtener_parametro_transporte(conn, 'transporte_tarifa_base', 5000)
            ingreso_objetivo = obtener_parametro_transporte(conn, 'transporte_ingreso_hora_objetivo', 30000)
            velocidad_pico = obtener_parametro_transporte(conn, 'transporte_velocidad_pico', 10)
            velocidad_valle = obtener_parametro_transporte(conn, 'transporte_velocidad_valle', 17)
            tiempo_espera = obtener_parametro_transporte(conn, 'transporte_tiempo_espera_recogida', 8)
            redondeo = obtener_parametro_transporte(conn, 'transporte_redondeo_tarifa', 500)

            # Determinar si es hora pico o valle (usa fecha programada si viene)
            fecha_hora_evaluar = None
            if fecha_programada_str:
                from datetime import datetime
                try:
                    fecha_hora_evaluar = datetime.fromisoformat(fecha_programada_str)
                except:
                    pass
            hora_pico = es_hora_pico(conn, fecha_hora_evaluar)

            # Calcular tarifa por km según horario
            if hora_pico:
                velocidad = velocidad_pico
                tarifa_km = ingreso_objetivo / velocidad_pico
            else:
                velocidad = velocidad_valle
                tarifa_km = ingreso_objetivo / velocidad_valle

            # Calcular tiempo estimado
            tiempo_recorrido = (distancia_km / velocidad) * 60  # en minutos
            tiempo_total = tiempo_recorrido + tiempo_espera

            # Calcular tarifa con redondeo
            recorrido_sin_redondeo = distancia_km * tarifa_km
            recorrido_redondeado = round(recorrido_sin_redondeo / redondeo) * redondeo
            tarifa = tarifa_base + recorrido_redondeado + total_peajes

            desglose = {
                'base': int(tarifa_base),
                'recorrido': int(recorrido_redondeado),
                'tarifa_km': round(tarifa_km),
                'hora_pico': hora_pico,
                'tiempo_recorrido_min': round(tiempo_recorrido, 1),
                'tiempo_total_min': round(tiempo_total, 1),
                'peajes': peajes_detectados,
                'total_peajes': int(total_peajes),
                'total': int(tarifa)
            }

        elif tipo_servicio == 'acompanamiento':
            # Obtener parámetros configurables
            tarifa_hora = obtener_parametro_transporte(conn, 'acompanamiento_tarifa_hora', 30000)
            horas_minimo = obtener_parametro_transporte(conn, 'acompanamiento_horas_minimo', 1)

            if not horas or horas < horas_minimo:
                horas = horas_minimo

            tarifa = horas * tarifa_hora

            desglose = {
                'horas': horas,
                'tarifa_hora': int(tarifa_hora),
                'horas_minimo': int(horas_minimo),
                'total': int(tarifa)
            }

        else:
            conn.close()
            return jsonify({'ok': False, 'error': 'Tipo de servicio inválido'}), 400

        conn.close()

        return jsonify({
            'ok': True,
            'tarifa': int(tarifa),
            'desglose': desglose
        })

    except Exception as e:
        print(f"Error en calcular-tarifa: {e}")
        traceback.print_exc()
        return jsonify({'ok': False, 'error': str(e)}), 500


@app.route('/api/solicitar-servicio', methods=['POST'])
def api_solicitar_servicio():
    """
    Crea una nueva solicitud de servicio de transporte

    Body JSON:
    {
        "tipo_servicio": "transporte" | "acompanamiento",
        "telefono": "3175718658",
        "nombre": "Rafael Olivares",
        "origen_texto": "Calle 5 Norte 23-45, Cali",
        "destino_texto": "Avenida 6 Norte 28-50, Cali",
        "distancia_km": 5.2,
        "tiempo_estimado_minutos": 15,
        "precio": 15400,
        "horas_acompanamiento": null,  # Solo para acompañamiento
        "notas": "Llevar silla de ruedas"
    }
    """
    try:
        data = request.get_json()
        conn = get_db_connection()

        # Verificar si hay usuario logueado
        if 'usuario_id' in session:
            # Usuario logueado: usar su ID directamente
            tercero_id = session['usuario_id']

            # Obtener datos del usuario para la notificación
            tercero_data = conn.execute("""
                SELECT nombre, telefono FROM terceros WHERE id = %s
            """, (tercero_id,)).fetchone()

            nombre = tercero_data['nombre']
            telefono = tercero_data['telefono']
        else:
            # Usuario no logueado: buscar o crear tercero por teléfono
            telefono = data.get('telefono')
            nombre = data.get('nombre')

            if not telefono or not nombre:
                return jsonify({'ok': False, 'error': 'Teléfono y nombre son requeridos'}), 400

            # Buscar tercero existente
            tercero = conn.execute("""
                SELECT id, nombre FROM terceros WHERE telefono = %s
            """, (telefono,)).fetchone()

            usuario_nuevo = False
            if tercero:
                tercero_id = tercero['id']
                nombre = tercero['nombre']  # Usar nombre existente
            else:
                # Crear nuevo tercero con referido si existe
                referido_por = data.get('referido_por')
                if referido_por:
                    tercero_id = conn.execute("""
                        INSERT INTO terceros (nombre, telefono, fecha_creacion, referido_por)
                        VALUES (%s, %s, CURRENT_TIMESTAMP, %s)
                        RETURNING id
                    """, (nombre, telefono, referido_por)).fetchone()['id']
                else:
                    tercero_id = conn.execute("""
                        INSERT INTO terceros (nombre, telefono, fecha_creacion)
                        VALUES (%s, %s, CURRENT_TIMESTAMP)
                        RETURNING id
                    """, (nombre, telefono)).fetchone()['id']
                conn.commit()
                usuario_nuevo = True

            # LOGUEAR AL USUARIO AUTOMÁTICAMENTE
            session['usuario_id'] = tercero_id
            session['nombre'] = nombre
            session['telefono'] = telefono
            session['rol'] = 'Cliente'
            session.permanent = True

            # Copiar push_token de USUARIOS a terceros si existe
            if 'dispositivo_id' in session:
                usuario_rec = conn.execute('SELECT push_token FROM "USUARIOS" WHERE dispositivo_id = %s',
                                           (session['dispositivo_id'],)).fetchone()
                if usuario_rec and usuario_rec['push_token']:
                    conn.execute("UPDATE terceros SET push_token = %s WHERE id = %s",
                                 (usuario_rec['push_token'], tercero_id))
                    conn.commit()

        # Crear solicitud
        tipo_servicio = data.get('tipo_servicio')
        origen_texto = data.get('origen_texto')
        destino_texto = data.get('destino_texto')
        origen_lat = data.get('origen_lat')
        origen_lon = data.get('origen_lon')
        destino_lat = data.get('destino_lat')
        destino_lon = data.get('destino_lon')
        distancia_km = data.get('distancia_km')
        tiempo_estimado_minutos = data.get('tiempo_estimado_minutos')
        precio = data.get('precio')
        horas_acompanamiento = data.get('horas_acompanamiento')
        notas = data.get('notas')
        fecha_programada = data.get('fecha_programada')
        hora_programada = data.get('hora_programada')
        horas_programadas = data.get('horas_programadas')

        # Validar que no tenga viajes que se solapen
        puede_solicitar, mensaje_error = validar_solapamiento_pasajero(
            conn, tercero_id, fecha_programada, tiempo_estimado_minutos
        )
        if not puede_solicitar:
            conn.close()
            return jsonify({'ok': False, 'error': mensaje_error}), 400

        solicitud_id = conn.execute("""
            INSERT INTO solicitudes_transporte (
                tercero_id, tipo_servicio, origen_texto, destino_texto,
                origen_lat, origen_lon, destino_lat, destino_lon,
                distancia_km, tiempo_estimado_minutos, precio,
                horas_acompanamiento, notas, estado, fecha_solicitud, fecha_servicio,
                fecha_programada, hora_programada, horas_programadas
            )
            VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, 'pendiente', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, %s, %s, %s)
            RETURNING id
        """, (
            tercero_id, tipo_servicio, origen_texto, destino_texto,
            origen_lat, origen_lon, destino_lat, destino_lon,
            distancia_km, tiempo_estimado_minutos, precio,
            horas_acompanamiento, notas,
            fecha_programada, hora_programada, horas_programadas
        )).fetchone()['id']

        conn.commit()

        # Enviar notificación por Telegram
        mensaje = f"""
🚗 NUEVA SOLICITUD DE SERVICIO

📋 Solicitud #{solicitud_id}
👤 Cliente: {nombre}
📞 Teléfono: {telefono}

🔹 Tipo: {tipo_servicio.upper()}
"""

        if tipo_servicio == 'transporte':
            # Obtener coordenadas desde el frontend
            origen_lat = data.get('origen_lat')
            origen_lon = data.get('origen_lon')
            destino_lat = data.get('destino_lat')
            destino_lon = data.get('destino_lon')

            mensaje += f"""
📍 Origen: {origen_texto}
📍 Destino: {destino_texto}
📏 Distancia: {distancia_km} km
⏱️ Tiempo estimado: {tiempo_estimado_minutos} min
💰 Tarifa: ${precio:,.0f}

🗺️ RUTAS WAZE:
1️⃣ Tu ubicación → Cliente: https://waze.com/ul?ll={origen_lat},{origen_lon}&navigate=yes
2️⃣ Cliente → Destino: https://waze.com/ul?ll={destino_lat},{destino_lon}&navigate=yes
"""
        elif tipo_servicio == 'acompanamiento':
            mensaje += f"""
⏰ Horas: {horas_acompanamiento}
💰 Tarifa: ${precio:,.0f}
"""

        if notas:
            mensaje += f"\n📝 Notas: {notas}"

        # Enviar notificación a Rafael (3175718658)
        enviar_telegram('3175718658', mensaje)

        conn.close()

        # Determinar si el usuario fue creado o ya existía
        usuario_info = {
            'id': tercero_id,
            'nombre': nombre,
            'telefono': telefono,
            'nuevo': usuario_nuevo if 'usuario_nuevo' in dir() else False
        }

        return jsonify({
            'ok': True,
            'solicitud_id': solicitud_id,
            'mensaje': 'Solicitud creada exitosamente',
            'usuario': usuario_info
        })

    except Exception as e:
        return jsonify({'ok': False, 'error': str(e)}), 500


