@app.route('/api/conductor/captura', methods=['POST'])
def api_conductor_captura():
    """Guarda una captura de pasajero prospecto y genera token de invitación"""
    if 'usuario_id' not in session:
        return jsonify({'ok': False, 'error': 'No autenticado'}), 401

    import uuid
    data = request.get_json()
    nombre = data.get('nombre', '').strip()
    tarifa_referencia = data.get('tarifa_referencia')
    tarifa_final = data.get('tarifa_final')
    telefono = data.get('telefono') or None
    punto_a_lat = data.get('punto_a_lat')
    punto_a_lon = data.get('punto_a_lon')
    punto_a_etiqueta = data.get('punto_a_etiqueta', '')
    punto_b_lat = data.get('punto_b_lat')
    punto_b_lon = data.get('punto_b_lon')
    punto_b_etiqueta = data.get('punto_b_etiqueta', '')

    if not nombre:
        return jsonify({'ok': False, 'error': 'Nombre requerido'}), 400
    if not tarifa_referencia:
        return jsonify({'ok': False, 'error': 'Tarifa requerida'}), 400
    if not punto_a_lat or not punto_b_lat:
        return jsonify({'ok': False, 'error': 'Ambos puntos GPS son requeridos'}), 400

    token = uuid.uuid4().hex[:12]
    precio_oferta = float(tarifa_final or tarifa_referencia) - 5000
    if precio_oferta < 0:
        precio_oferta = 0

    try:
        conn = get_db_connection()

        # Self-healing: crear tabla si no existe
        conn.execute("""
            CREATE TABLE IF NOT EXISTS capturas_pasajero (
                id SERIAL PRIMARY KEY,
                conductor_id INTEGER NOT NULL,
                tercero_id INTEGER,
                nombre VARCHAR(255) NOT NULL,
                tarifa_referencia DECIMAL(10,2),
                tarifa_final DECIMAL(10,2),
                telefono VARCHAR(20),
                punto_a_lat DECIMAL(10,8),
                punto_a_lon DECIMAL(11,8),
                punto_a_etiqueta VARCHAR(50),
                punto_b_lat DECIMAL(10,8),
                punto_b_lon DECIMAL(11,8),
                punto_b_etiqueta VARCHAR(50),
                token VARCHAR(20),
                precio_oferta DECIMAL(10,2),
                estado VARCHAR(20) DEFAULT 'completada',
                created_at TIMESTAMP DEFAULT NOW()
            )
        """)

        # Self-healing: agregar columnas si no existen (cada uno aislado)
        for alter in [
            "ALTER TABLE capturas_pasajero ADD COLUMN IF NOT EXISTS token VARCHAR(20)",
            "ALTER TABLE capturas_pasajero ADD COLUMN IF NOT EXISTS precio_oferta DECIMAL(10,2)",
            "ALTER TABLE capturas_pasajero ADD COLUMN IF NOT EXISTS tercero_id INTEGER",
        ]:
            try:
                conn.execute(alter)
                conn.commit()
            except Exception:
                conn.rollback()

        # Self-healing: descuento_bienvenida en terceros (renombrar si existía como credito_bienvenida)
        try:
            conn.execute("ALTER TABLE terceros RENAME COLUMN credito_bienvenida TO descuento_bienvenida")
        except Exception:
            conn.rollback()
        try:
            conn.execute("ALTER TABLE terceros ADD COLUMN IF NOT EXISTS descuento_bienvenida INTEGER DEFAULT 0")
        except Exception:
            conn.rollback()

        # Pre-crear usuario en terceros con bono de $5,000
        tercero_id = None
        if telefono:
            # Si ya existe un usuario con ese teléfono, vincularlo y darle crédito
            existente = conn.execute(
                "SELECT id FROM terceros WHERE telefono = %s", (telefono,)
            ).fetchone()
            if existente:
                tercero_id = existente[0]
                conn.execute("""
                    UPDATE terceros SET descuento_bienvenida = GREATEST(descuento_bienvenida, %s)
                    WHERE id = %s
                """, (int(precio_oferta), tercero_id))
            else:
                cur = conn.execute("""
                    INSERT INTO terceros (nombre, telefono, referido_por, descuento_bienvenida, fecha_creacion)
                    VALUES (%s, %s, %s, %s, NOW())
                    RETURNING id
                """, (nombre, telefono, session['usuario_id'], int(precio_oferta)))
                row = cur.fetchone()
                tercero_id = row[0] if row else None
        else:
            # Sin teléfono: crear usuario solo con nombre + crédito
            cur = conn.execute("""
                INSERT INTO terceros (nombre, referido_por, descuento_bienvenida, fecha_creacion)
                VALUES (%s, %s, %s, NOW())
                RETURNING id
            """, (nombre, session['usuario_id'], int(precio_oferta)))
            row = cur.fetchone()
            tercero_id = row[0] if row else None

        conn.execute("""
            INSERT INTO capturas_pasajero
            (conductor_id, tercero_id, nombre, tarifa_referencia, tarifa_final, telefono,
             punto_a_lat, punto_a_lon, punto_a_etiqueta,
             punto_b_lat, punto_b_lon, punto_b_etiqueta,
             token, precio_oferta)
            VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s)
        """, (session['usuario_id'], tercero_id, nombre, tarifa_referencia, tarifa_final, telefono,
              punto_a_lat, punto_a_lon, punto_a_etiqueta,
              punto_b_lat, punto_b_lon, punto_b_etiqueta,
              token, precio_oferta))

        conn.commit()
        conn.close()
        return jsonify({
            'ok': True,
            'token': token,
            'precio_oferta': precio_oferta,
            'nombre': nombre,
            'telefono': telefono
        })
    except Exception as e:
        return jsonify({'ok': False, 'error': str(e)}), 500


@app.route('/i/<token>')
def invitacion_pasajero(token):
    """Auto-login del pasajero pre-creado via token de captura"""
    try:
        conn = get_db_connection()
        captura = conn.execute("""
            SELECT tercero_id, nombre, telefono, precio_oferta,
                   punto_a_etiqueta, punto_b_etiqueta
            FROM capturas_pasajero WHERE token = %s
        """, (token,)).fetchone()

        if not captura:
            conn.close()
            return redirect('/servicios')

        tercero_id = captura[0]
        nombre = captura[1]
        telefono = captura[2]

        if tercero_id:
            # Auto-login
            session['usuario_id'] = tercero_id
            session['nombre'] = nombre
            if telefono:
                session['telefono'] = telefono
            session['rol'] = 'Cliente'
            session.permanent = True

        conn.close()
        return redirect('/servicios')
    except Exception:
        return redirect('/servicios')


@app.route('/api/usuario/actualizar-telefono', methods=['POST'])
def api_usuario_actualizar_telefono():
    """Actualiza el teléfono de un usuario logueado (para usuarios pre-creados sin teléfono)"""
    if 'usuario_id' not in session:
        return jsonify({'ok': False, 'error': 'No autenticado'}), 401

    data = request.get_json()
    telefono = (data.get('telefono') or '').strip()
    telefono = ''.join(c for c in telefono if c.isdigit())

    if len(telefono) < 10:
        return jsonify({'ok': False, 'error': 'Teléfono debe tener al menos 10 dígitos'}), 400

    try:
        conn = get_db_connection()

        # Verificar que no exista otro usuario con ese teléfono
        existente = conn.execute(
            "SELECT id FROM terceros WHERE telefono = %s AND id != %s",
            (telefono, session['usuario_id'])
        ).fetchone()

        if existente:
            conn.close()
            return jsonify({'ok': False, 'error': 'Este teléfono ya está registrado'}), 400

        conn.execute(
            "UPDATE terceros SET telefono = %s WHERE id = %s",
            (telefono, session['usuario_id'])
        )
        conn.commit()
        conn.close()

        session['telefono'] = telefono
        return jsonify({'ok': True})
    except Exception as e:
        return jsonify({'ok': False, 'error': str(e)}), 500


@app.route('/api/usuario-actual')
def api_usuario_actual():
    """
    Retorna información del usuario actualmente logueado
    """
    if 'usuario_id' not in session:
        return jsonify({'ok': False, 'usuario': None})

    try:
        conn = get_db_connection()
        # Self-healing: descuento_bienvenida
        try:
            conn.execute("ALTER TABLE terceros ADD COLUMN IF NOT EXISTS descuento_bienvenida INTEGER DEFAULT 0")
        except Exception:
            conn.rollback()

        usuario = conn.execute("""
            SELECT id, nombre, telefono, placa, color_vehiculo, marca_vehiculo, modelo_vehiculo,
                   COALESCE(descuento_bienvenida, 0) as descuento_bienvenida
            FROM terceros
            WHERE id = %s
        """, (session['usuario_id'],)).fetchone()

        if usuario:
            # Extraer primer nombre
            primer_nombre = usuario['nombre'].split(' ')[0] if usuario['nombre'] else 'Usuario'

            return jsonify({
                'ok': True,
                'usuario': {
                    'id': usuario['id'],
                    'nombre': usuario['nombre'],
                    'telefono': usuario['telefono'] or '',
                    'primer_nombre': primer_nombre,
                    'placa': usuario['placa'],
                    'color_vehiculo': usuario['color_vehiculo'],
                    'marca_vehiculo': usuario['marca_vehiculo'],
                    'modelo_vehiculo': usuario['modelo_vehiculo'],
                    'descuento_bienvenida': usuario['descuento_bienvenida']
                }
            })
        else:
            return jsonify({'ok': False, 'usuario': None})

    except Exception as e:
        print(f"Error al obtener usuario actual: {e}")
        return jsonify({'ok': False, 'error': str(e)})


