@app.route('/api/restaurante/<slug>/mesa', methods=['POST'])
def api_restaurante_mesa_crear(slug):
    """Crear mesa"""
    if 'usuario_id' not in session:
        return jsonify({'ok': False, 'error': 'No autenticado'}), 401

    data = request.get_json()
