@app.route('/api/restaurante/<slug>/verificar-pin', methods=['POST'])
def api_restaurante_verificar_pin(slug):
    """Verifica PIN de mesero o cocina"""
    data = request.get_json()
    pin = data.get('pin', '').strip()
    rol = data.get('rol', '')  # 'mesero' o 'cocina'

    if rol not in ('mesero', 'cocina'):
        return jsonify({'ok': False, 'error': 'Rol inválido'}), 400

    try:
        conn = get_db_connection()
        crear_tablas_restaurante(conn)
        rest = conn.execute(
            "SELECT id, pin_mesero, pin_cocina FROM restaurantes WHERE slug = %s AND activo = TRUE", (slug,)
        ).fetchone()
        conn.close()
        if not rest:
            return jsonify({'ok': False, 'error': 'No encontrado'}), 404

        pin_correcto = rest[f'pin_{rol}']
        if not pin_correcto:
            return jsonify({'ok': False, 'error': 'El administrador aún no ha configurado el PIN de acceso'}), 400
        if pin == pin_correcto:
            return jsonify({'ok': True})
        return jsonify({'ok': False, 'error': 'PIN incorrecto'}), 400
    except Exception as e:
        return jsonify({'ok': False, 'error': str(e)}), 500


# ===== RESTAURANTE: SUSCRIPCIÓN / DÍAS =====

@app.route('/api/restaurante/<slug>/suscripcion')
def api_restaurante_suscripcion(slug):
    """Consultar estado de suscripción"""
    try:
        conn = get_db_connection()
        crear_tablas_restaurante(conn)
        rest = conn.execute(
            "SELECT id, dias_pagados FROM restaurantes WHERE slug = %s AND activo = TRUE", (slug,)
        ).fetchone()
        if not rest:
            conn.close()
            return jsonify({'ok': False, 'error': 'No encontrado'}), 404

        dias_pagados = rest['dias_pagados'] or 0
        dias_usados = conn.execute("""
            SELECT COUNT(DISTINCT DATE(created_at)) as dias
            FROM pedidos_restaurante WHERE restaurante_id = %s
        """, (rest['id'],)).fetchone()['dias']
        conn.close()

        return jsonify({
            'ok': True,
            'dias_pagados': dias_pagados,
            'dias_usados': dias_usados,
            'dias_restantes': max(0, dias_pagados - dias_usados)
        })
    except Exception as e:
        return jsonify({'ok': False, 'error': str(e)}), 500


@app.route('/api/restaurante/<slug>/dias-pagados', methods=['POST'])
def api_restaurante_dias_pagados(slug):
    """Agregar días pagados y registrar en historial (solo admin del sistema)"""
    if session.get('rol') != 'Administrador':
        return jsonify({'ok': False, 'error': 'Solo administradores'}), 403

    data = request.get_json()
    dias = data.get('dias')
    nota = data.get('nota', '').strip()
    if not dias or not isinstance(dias, int) or dias <= 0:
        return jsonify({'ok': False, 'error': 'Número de días inválido'}), 400

    try:
        conn = get_db_connection()
        crear_tablas_restaurante(conn)
        rest = conn.execute("SELECT id, dias_pagados FROM restaurantes WHERE slug = %s AND activo = TRUE", (slug,)).fetchone()
        if not rest:
            conn.close()
            return jsonify({'ok': False, 'error': 'No encontrado'}), 404

        nuevo_total = (rest['dias_pagados'] or 0) + dias

        conn.execute(
            "UPDATE restaurantes SET dias_pagados = %s WHERE id = %s",
            (nuevo_total, rest['id'])
        )
        conn.execute(
            "INSERT INTO pagos_restaurante (restaurante_id, dias, nota) VALUES (%s, %s, %s)",
            (rest['id'], dias, nota or None)
        )
        conn.commit()
        conn.close()
        return jsonify({'ok': True, 'nuevo_total': nuevo_total})
    except Exception as e:
        return jsonify({'ok': False, 'error': str(e)}), 500


@app.route('/api/restaurante/<slug>/pagos')
def api_restaurante_pagos(slug):
    """Historial de pagos/recargas de días"""
    try:
        conn = get_db_connection()
        crear_tablas_restaurante(conn)
        rest = conn.execute("SELECT id FROM restaurantes WHERE slug = %s AND activo = TRUE", (slug,)).fetchone()
        if not rest:
            conn.close()
            return jsonify({'ok': False, 'error': 'No encontrado'}), 404

        pagos = conn.execute("""
            SELECT dias, nota, created_at FROM pagos_restaurante
            WHERE restaurante_id = %s ORDER BY created_at DESC
        """, (rest['id'],)).fetchall()
        conn.close()

        return jsonify({'ok': True, 'pagos': [
            {'dias': p['dias'], 'nota': p['nota'] or '', 'fecha': p['created_at'].strftime('%Y-%m-%d %H:%M')}
            for p in pagos
        ]})
    except Exception as e:
        return jsonify({'ok': False, 'error': str(e)}), 500


