@app.route('/api/restaurante/<slug>/registrar-cliente', methods=['POST'])
def api_restaurante_registrar_cliente(slug):
    """Registra/identifica cliente para pedido remoto, lo loguea"""
    data = request.get_json()
    nombre = data.get('nombre', '').strip()
    telefono = ''.join(filter(str.isdigit, data.get('telefono', '')))
    direccion = data.get('direccion', '').strip()

    if not nombre:
        return jsonify({'ok': False, 'error': 'Nombre requerido'}), 400
    if len(telefono) < 10:
        return jsonify({'ok': False, 'error': 'Celular debe tener al menos 10 dígitos'}), 400

    try:
        conn = get_db_connection()
        # Buscar o crear tercero
        tercero = conn.execute(
            "SELECT id, nombre FROM terceros WHERE telefono = %s LIMIT 1", (telefono,)
        ).fetchone()
        if tercero:
            cliente_id = tercero['id']
            conn.execute("UPDATE terceros SET nombre = %s, direccion = %s WHERE id = %s",
                         (nombre, direccion or None, cliente_id))
        else:
            conn.execute(
                "INSERT INTO terceros (nombre, telefono, direccion) VALUES (%s, %s, %s)",
                (nombre, telefono, direccion or None)
            )
            cliente_id = conn.execute("SELECT id FROM terceros WHERE telefono = %s", (telefono,)).fetchone()['id']

        conn.commit()
        conn.close()

        # Loguear
        session['usuario_id'] = cliente_id
        session['nombre'] = nombre
        session['telefono'] = telefono
        session['rol'] = 'Cliente'
        session.permanent = True
        session.modified = True

        return jsonify({'ok': True, 'cliente_id': cliente_id})
    except Exception as e:
        return jsonify({'ok': False, 'error': str(e)}), 500


@app.route('/api/restaurante/<slug>/pedido', methods=['POST'])
def api_restaurante_pedido_crear(slug):
    """Crear pedido(s) — soporta menu_dia y carta"""
    data = request.get_json()
    mesa_num = int(data.get('mesa_num', 0))
    nombre_cliente = data.get('nombre_cliente', '').strip() or None
    notas = data.get('notas', '').strip()
    tipo_entrega = data.get('tipo_entrega', 'mesa')
    telefono_cliente = data.get('telefono_cliente', '').strip() or None if data.get('telefono_cliente') else None
    direccion_cliente = data.get('direccion_cliente', '').strip() or None if data.get('direccion_cliente') else None
    cliente_id = data.get('cliente_id')

    try:
        conn = get_db_connection()
        crear_tablas_restaurante(conn)
        rest = conn.execute("SELECT id, tipo_restaurante, dias_pagados FROM restaurantes WHERE slug = %s", (slug,)).fetchone()
        if not rest:
            conn.close()
            return jsonify({'ok': False, 'error': 'Restaurante no encontrado'}), 404

        # Verificar suscripción: ¿tiene días disponibles?
        dias_pagados = rest['dias_pagados'] or 0
        if dias_pagados > 0:
            dias_usados = conn.execute("""
                SELECT COUNT(DISTINCT DATE(created_at)) as dias
                FROM pedidos_restaurante WHERE restaurante_id = %s
            """, (rest['id'],)).fetchone()['dias']

            # Si hoy ya tiene pedidos, no consume un día nuevo
            tiene_pedidos_hoy = conn.execute("""
                SELECT 1 FROM pedidos_restaurante
                WHERE restaurante_id = %s AND DATE(created_at) = CURRENT_DATE
                LIMIT 1
            """, (rest['id'],)).fetchone()

            if not tiene_pedidos_hoy and dias_usados >= dias_pagados:
                conn.close()
                return jsonify({'ok': False, 'error': 'suscripcion_agotada', 'dias_pagados': dias_pagados, 'dias_usados': dias_usados}), 402

        precio_total = 0

        if rest['tipo_restaurante'] == 'carta':
            # CARTA: recibe lista de platos [{plato_id, cantidad}]
            platos = data.get('platos', [])
            if not platos:
                conn.close()
                return jsonify({'ok': False, 'error': 'Selecciona al menos un plato'}), 400

            for p in platos:
                opcion = conn.execute(
                    "SELECT id, nombre, precio FROM opciones_menu WHERE id = %s AND restaurante_id = %s AND activo = TRUE",
                    (p['plato_id'], rest['id'])
                ).fetchone()
                if not opcion:
                    continue
                cant = p.get('cantidad', 1)
                precio_item = float(opcion['precio']) * cant
                precio_total += precio_item
                conn.execute("""
                    INSERT INTO pedidos_restaurante (restaurante_id, mesa_num, tipo, plato_id, cantidad, precio, notas, nombre_cliente, tipo_entrega, telefono_cliente, direccion_cliente, cliente_id)
                    VALUES (%s, %s, 'carta', %s, %s, %s, %s, %s, %s, %s, %s, %s)
                """, (rest['id'], mesa_num, opcion['id'], cant, precio_item, notas or None, nombre_cliente, tipo_entrega, telefono_cliente, direccion_cliente, cliente_id))

        else:
            # MENU_DIA: flujo original
            tipo = data.get('tipo')
            sopa_id = data.get('sopa_id')
            proteina_id = data.get('proteina_id')
            principio_id = data.get('principio_id')

            if tipo not in ('completo', 'bandeja', 'sopa'):
                conn.close()
                return jsonify({'ok': False, 'error': 'Tipo requerido'}), 400

            from datetime import date
            menu = conn.execute("""
                SELECT id, precio_completo, precio_bandeja, precio_sopa
                FROM menu_dia WHERE restaurante_id = %s AND fecha = %s AND activo = TRUE
            """, (rest['id'], date.today().isoformat())).fetchone()

            if not menu:
                conn.close()
                return jsonify({'ok': False, 'error': 'No hay menú configurado para hoy'}), 400

            if tipo == 'completo':
                precio_total = float(menu['precio_completo'])
            elif tipo == 'bandeja':
                precio_total = float(menu['precio_bandeja'])
            else:
                precio_total = float(menu['precio_sopa'])

            if proteina_id and tipo in ('completo', 'bandeja'):
                recargo = conn.execute(
                    "SELECT recargo FROM opciones_menu WHERE id = %s", (proteina_id,)
                ).fetchone()
                if recargo and recargo['recargo']:
                    precio_total += float(recargo['recargo'])

            conn.execute("""
                INSERT INTO pedidos_restaurante (restaurante_id, mesa_num, tipo, sopa_id, proteina_id, principio_id, precio, notas, nombre_cliente, tipo_entrega, telefono_cliente, direccion_cliente, cliente_id)
                VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s)
            """, (rest['id'], mesa_num, tipo, sopa_id, proteina_id, principio_id, precio_total, notas or None, nombre_cliente, tipo_entrega, telefono_cliente, direccion_cliente, cliente_id))

        conn.commit()
        conn.close()
        return jsonify({'ok': True, 'precio': precio_total})
    except Exception as e:
        return jsonify({'ok': False, 'error': str(e)}), 500


@app.route('/api/restaurante/<slug>/pedidos')
def api_restaurante_pedidos(slug):
    """Listar pedidos (filtrable por estado)"""
    estado = request.args.get('estado', 'pendiente,listo')
    estados = [e.strip() for e in estado.split(',')]

    try:
        conn = get_db_connection()
        crear_tablas_restaurante(conn)
        rest = conn.execute("SELECT id FROM restaurantes WHERE slug = %s", (slug,)).fetchone()
        if not rest:
            conn.close()
            return jsonify({'ok': False, 'error': 'Restaurante no encontrado'}), 404

        placeholders = ','.join(['%s'] * len(estados))
        pedidos = conn.execute(f"""
            SELECT p.id, p.mesa_num, p.tipo, p.precio, p.estado, p.notas, p.nombre_cliente, p.created_at,
                   p.cantidad, p.tipo_entrega, p.telefono_cliente, p.direccion_cliente, p.cliente_id,
                   s.nombre as sopa_nombre,
                   pr.nombre as proteina_nombre, pr.recargo as proteina_recargo,
                   pi.nombre as principio_nombre,
                   pl.nombre as plato_nombre
            FROM pedidos_restaurante p
            LEFT JOIN opciones_menu s ON s.id = p.sopa_id
            LEFT JOIN opciones_menu pr ON pr.id = p.proteina_id
            LEFT JOIN opciones_menu pi ON pi.id = p.principio_id
            LEFT JOIN opciones_menu pl ON pl.id = p.plato_id
            WHERE p.restaurante_id = %s AND p.estado IN ({placeholders})
            AND p.created_at::date = CURRENT_DATE
            ORDER BY p.created_at DESC
        """, (rest['id'], *estados)).fetchall()

        conn.close()
        resultado = []
        for p in pedidos:
            resultado.append({
                'id': p['id'],
                'mesa_num': p['mesa_num'],
                'tipo': p['tipo'],
                'precio': float(p['precio']),
                'estado': p['estado'],
                'notas': p['notas'],
                'sopa': p['sopa_nombre'],
                'proteina': p['proteina_nombre'],
                'proteina_recargo': float(p['proteina_recargo']) if p['proteina_recargo'] else 0,
                'principio': p['principio_nombre'],
                'plato': p['plato_nombre'],
                'cantidad': p['cantidad'] or 1,
                'nombre_cliente': p['nombre_cliente'],
                'tipo_entrega': p['tipo_entrega'] or 'mesa',
                'telefono_cliente': p['telefono_cliente'],
                'direccion_cliente': p['direccion_cliente'],
                'cliente_id': p['cliente_id'],
                'created_at': p['created_at'].strftime('%H:%M') if p['created_at'] else ''
            })
        return jsonify({'ok': True, 'pedidos': resultado})
    except Exception as e:
        return jsonify({'ok': False, 'error': str(e)}), 500


